  signin: 'Sign in failed. Please try again.',
  signup: 'Sign up failed. Please try again.',
} as const;

export const FIELDS = {
  signin: ['email', 'password'],
  signup: ['username', 'email', 'password', 'passwordConfirm'],
} as const;

export const AUTH_FUNC = {
  signin: signIn,
  signup: signUp,
} as const;

