      posts: {
        where: and(eq(posts.published, true), eq(posts.visibility, 'public')),
        columns: {
          id: true,
          title: true,
          description: true,
          published: true,
          visibility: true,
          createdAt: true
        },
        orderBy: desc(posts.createdAt),
        with: {
