import from "react" { useEffect }
import from "twilio-video" { AudioTrack as TwilioAudioTrack }

def attach_audio_track(track: TwilioAudioTrack, element: HTMLAudioElement | None) {
    if element {
        track.attach(element);
    }
}

def detach_audio_track(track: TwilioAudioTrack, element: HTMLAudioElement | None) {
    if element {
        track.detach(element);
    }
}

def run_audio_effect(track: TwilioAudioTrack, audio_ref: Ref[HTMLAudioElement]) -> Callable[[], None] {
    attach_audio_track(track, audio_ref.current);
    return lambda {
        detach_audio_track(track, audio_ref.current);
    };
}

def:pub AudioTrack(track: TwilioAudioTrack) -> JsxElement {
    has audioRef: Ref[HTMLAudioElement] = Ref();

    useEffect(lambda {
        return run_audio_effect(track, audioRef);
    }, [track]);

    return <audio ref={audioRef} autoPlay />;
}

