    selectedClass = "text-dd-primary" if selected else "";
    mergedClass = (selectedClass + " relative flex cursor-pointer items-center justify-center text-xl hover:opacity-70 " + className).strip();

    return <div className={mergedClass} onClick={handle_click}>
        {children}
        {_renderIndicator()}
    </div>;
}

