obj LoggerDeps {
    has logger: object;
}

def withLogger[T](run: Callable[[LoggerDeps], T]) -> Callable[[LoggerDeps], T] {
    return run;
}

def logError(e: dict[str, object]) -> Callable[[LoggerDeps], dict[str, object]] {
    def apply(deps: LoggerDeps) -> dict[str, object] {
        error_val = e["error"];
        context = {k: v for (k, v) in e.items() if k != "error"};
        getattr(deps.logger, "error")(error_val, context);
        return e;
    }
    return withLogger(apply);
}

