	tip: "bg-amber-400",
	tone: "bg-violet-400",
	gem: "bg-[#FFD94A]",
};

export function CoachTipBody({
	tip,
	rewrite,
	onApplyRewrite,
}: {
	tip: CoachTip;
	rewrite?: string | null;
	onApplyRewrite?: (text: string) => void;
}) {
	const [revealed, setRevealed] = useState(false);

	return (
