obj SubscriptionHandle {
    has closed: bool = False;
    def unsubscribe() {
        self.closed = True;
    }
}

import from "react" { useEffect, useCallback }

def:pub useSubscriptionRef() -> list[object] {
    subRef: Ref[SubscriptionHandle] = Ref();

    def cleanup_sub() {
        cur: SubscriptionHandle | None = subRef.current;
        if cur is not None and not cur.closed {
            cur.unsubscribe();
        }
    }

    useEffect(lambda {
        return lambda { cleanup_sub(); };
    }, []);

    unsubscribe = useCallback(lambda { cleanup_sub(); }, []);

    return [subRef, unsubscribe];
}

