});

describe("summarizeSession score", () => {
	const message = (author: "user" | "persona", tips?: CoachTip[]) => ({
		id: "m",
		author,
		text: "x",
		at: 0,
		tips,
	});
	const conversation = (messages: ReturnType<typeof message>[]) =>
		({
			id: "c",
			platform: "whatsapp",
			platformLabel: "WhatsApp Chat",
			topic: "t",
			persona: { name: "Maya", role: "Friend" },
			createdAt: 0,
			messages,
		}) as Conversation;

	it("averages per-message quality with severity penalties", () => {
		const oneFix = [{ ...fix }];
		const { score } = summarizeSession(
			conversation([message("user", []), message("user", oneFix)]),
		);
		expect(score).toBe(Math.round((100 + 85) / 2));
	});

	it("floors a heavily marked message at 40", () => {
		const pileOn = Array.from({ length: 10 }, () => ({ ...fix }));
		const { score } = summarizeSession(conversation([message("user", pileOn)]));
		expect(score).toBe(40);
	});

	it("ignores unanalyzed messages' tips but still counts them as sent", () => {
		const { score, sent } = summarizeSession(
			conversation([message("user"), message("persona", [])]),
		);
		expect(sent).toBe(1);
		expect(score).toBe(100);
	});
});

describe("draftMarks", () => {
	const review = (reviewedText: string, tips: CoachTip[]) => ({
		reviewedText,
		tips,
	});

	it("returns tips unchanged when the draft has no leading whitespace", () => {
		expect(draftMarks("idk yet", review("idk yet", [fix]))).toEqual([fix]);
	});

	it("shifts spans past leading whitespace the coach never saw", () => {
		const marks = draftMarks("\n  idk yet", review("idk yet", [fix]));
		expect(marks).toEqual([{ ...fix, start: 3, end: 6 }]);
	});

	it("keeps marks while only trailing whitespace is added", () => {
		expect(draftMarks("idk yet  ", review("idk yet", [fix]))).toEqual([fix]);
	});

	it("drops every mark once the draft text itself changes", () => {
		expect(draftMarks("idk yet more", review("idk yet", [fix]))).toEqual([]);
	});

	it("has nothing to place when the coach found nothing", () => {
		expect(draftMarks("idk yet", review("idk yet", []))).toEqual([]);
	});
});

