import from ..convex.coachScore { messageQuality }

type CoachKind = "fix" | "tip" | "tone" | "gem";

obj CoachTip {
    has kind: CoachKind;
    has start: int;
    has end: int;
    has title: str;
    has detail: str;
    has quote: str;
    has correction: str | None = None;
}

obj SessionInsights {
    has sent: int = 0;
    has clean: int = 0;
    has score: int | None = None;
    has toneMatch: int | None = None;
    has practice: list[CoachTip] = [];
    has gems: list[CoachTip] = [];
}

def tipsForMessage(message: dict[str, object]) -> list[CoachTip] {
    tips = message.get("tips");
    if tips is None {
        return [];
    }
    return tips as list[CoachTip];
}

def rewriteForMessage(message: dict[str, object]) -> str | None {
    if message["author"] != "user" {
        return None;
    }
    rewrite = message.get("rewrite");
    if rewrite is None {
        return None;
    }
    return rewrite as str;
}

def draftMarks(draft: str, review: dict[str, object]) -> list[CoachTip] {
    tips = review["tips"] as list[CoachTip];
    reviewedText = review["reviewedText"] as str;
    if len(tips) == 0 or draft.strip() != reviewedText {
        return [];
    }
    leadingWhitespace = len(draft) - len(draft.lstrip());
    if leadingWhitespace == 0 {
        return tips;
    }
    return [
        CoachTip(
            kind=tip.kind,
            start=tip.start + leadingWhitespace,
            end=tip.end + leadingWhitespace,
            title=tip.title,
            detail=tip.detail,
            quote=tip.quote,
            correction=tip.correction,
        )
        for tip in tips
    ];
}

def summarizeSession(conversation: dict[str, object]) -> SessionInsights {
    sent = 0;
    clean = 0;
    toneClean = 0;
    qualitySum = 0;
    practice: list[CoachTip] = [];
    gems: list[CoachTip] = [];
    seenPractice: dict[str, bool] = {};
    seenGems: dict[str, bool] = {};
    messages = conversation["messages"] as list[dict[str, object]];
    for message in messages {
        tips = tipsForMessage(message);
        if message["author"] == "user" {
            sent = sent + 1;
            if len(tips) == 0 {
                clean = clean + 1;
            }
            if not any(t.kind == "tone" for t in tips) {
                toneClean = toneClean + 1;
            }
            qualitySum = qualitySum + messageQuality(tips);
            for tip in tips {
                key = f"{tip.title}:{tip.quote.lower()}";
                if seenPractice.get(key) {
                    continue;
                }
                seenPractice[key] = True;
                practice = practice + [tip];
            }
        } else {
            for tip in tips {
                key = tip.quote.lower();
                if seenGems.get(key) {
                    continue;
                }
                seenGems[key] = True;
                gems = gems + [tip];
            }
        }
    }
    score = None;
    toneMatch = None;
    if sent > 0 {
        score = round(qualitySum / sent);
        toneMatch = round((toneClean / sent) * 100);
    }
    return SessionInsights(
        sent=sent,
        clean=clean,
        score=score,
        toneMatch=toneMatch,
        practice=practice,
        gems=gems,
    );
}

