async def fetchExchangeList(params: dict[str, object]) -> dict[str, object] {
    return {"data": [], "append": params["append"]};
}

def selectExchangeList(state: dict[str, object]) -> dict[str, object] {
    return state["exchangeList"] as dict[str, object];
}

def setExchangeQueryParams(payload: dict[str, object]) -> dict[str, object] {
    return {"type": "exchangeList/setExchangeQueryParams", "payload": payload};
}

def clearExchangeListValue() -> dict[str, object] {
    return {"type": "exchangeList/clearExchangeListValue"};
}

def reducer(state: dict[str, object], action: dict[str, object]) -> dict[str, object] {
    actionType = action["type"] as str;
    if actionType == "exchangeList/setExchangeQueryParams" {
        return {**state, "exchangeQueryParams": action["payload"]};
    }
    if actionType == "exchangeList/clearExchangeListValue" {
        perPage = state["exchangeQueryParams"]["perPage"] as int;
        value = state["value"] as list[object];
        return {
            **state,
            "value": value[:perPage],
            "exchangeQueryParams": {**state["exchangeQueryParams"] as dict[str, object], "page": 1},
            "hasMore": True,
        };
    }
    if actionType == "exchangeList/pending" {
        meta = action["meta"] as dict[str, object];
        arg = meta["arg"] as dict[str, object];
        status = "LOADING MORE" if arg["append"] else "LOADING";
        return {**state, "status": status};
    }
    if actionType == "exchangeList/fulfilled" {
        payload = action["payload"] as dict[str, object];
        data = payload["data"] as list[object];
        if payload["append"] as bool {
            oldValue = state["value"] as list[object];
            newValue = oldValue + data;
        } else {
            newValue = data;
        }
        hasMore = len(data) > 0;
        return {**state, "status": "IDLE", "value": newValue, "hasMore": hasMore};
    }
    if actionType == "exchangeList/rejected" {
        return {**state, "status": "FAILED", "error": action["error"]["message"]};
    }
    return state;
}

