import random;
import re;

def is_object(item: object) -> bool {
    return item is not None and isinstance(item, dict);
}

def merge(target: dict[str, object], *sources: dict[str, object]) -> dict[str, object] {
    for source in sources {
        for key in source.keys() {
            target_value = target[key] if key in target else None;
            source_value = source[key];
            if is_object(target_value) and is_object(source_value) {
                target[key] = merge(
                    target_value as dict[str, object],
                    source_value as dict[str, object]
                );
            } elif source_value is not None {
                target[key] = source_value;
            }
        }
    }
    return target;
}

obj UuidState {
    has counter: int = 0;
}

def _replace_uuid_char(m: re.Match[str]) -> str {
    c = m.group(0);
    r = int(random.random() * 16);
    v = r if c == "x" else (r & 0x3) | 0x8;
    return format(v, "x");
}

def generate_uuid() -> Callable[[bool], str] {
    state = UuidState();
    def uuid_fn(simple: bool = False) -> str {
        state.counter += 1;
        if simple {
            return str(state.counter);
        }
        template = "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx";
        body = re.sub(r"[xy]", _replace_uuid_char, template);
        return f"{body}-{state.counter}";
    }
    return uuid_fn;
}

glob uuid = generate_uuid();

def generateUniqueRandomNumbers(length: int, min: int, max: int) -> list[int] {
    if length > max - min + 1 {
        raise ValueError(
            "Cannot generate unique random numbers. Requested length is greater than the range of numbers."
        );
    }
    numbers: set[int] = set();
    while len(numbers) < length {
        numbers.add(random.randint(min, max));
    }
    return list(numbers);
}

obj TruncateOptions {
    has maxLength: int;
    has position: str = "end";
    has ellipsis: str = "...";
}

def truncateText(text: str, options: TruncateOptions) -> str {
    maxLength = options.maxLength;
    position = options.position;
    ellipsis = options.ellipsis;
    if len(text) <= maxLength {
        return text;
    }
    ellipsisLength = len(ellipsis);
    leftLength = (maxLength - ellipsisLength + 1) // 2;
    rightLength = (maxLength - ellipsisLength) // 2;
    match position {
        case "start":
            return ellipsis + text[-(maxLength - ellipsisLength):];
        case "middle":
            return text[:leftLength] + ellipsis + text[-rightLength:];
        case _:
            return text[: maxLength - ellipsisLength] + ellipsis;
    }
}

