glob TOAST_REMOVE_DELAY = 1000000;

glob actionTypes = {"ADD_TOAST": "ADD_TOAST", "UPDATE_TOAST": "UPDATE_TOAST", "DISMISS_TOAST": "DISMISS_TOAST", "REMOVE_TOAST": "REMOVE_TOAST"};

