import from react { useEffect, useRef }

glob DEFAULT_OPTIONS: dict[str, bool] = {"disabled": False};

def:pub useEventListener(eventType: str, handler: object, options: dict[str, bool] = DEFAULT_OPTIONS) -> object {
    disabled = options.get("disabled", False);
    handlerRef = useRef(handler);
    elementRef = useRef(None);
    useEffect(lambda {
        handlerRef.current = handler;
    }, [handler]);
    useEffect(lambda {
        if disabled {
            return None;
        }
        def eventHandler(e: Event) {
            if handlerRef.current is not None and elementRef.current is not None {
                handlerRef.current(elementRef.current, e);
            }
        }
        if elementRef.current is not None {
            elementRef.current.addEventListener(eventType, eventHandler);
        }
        return lambda {
            if elementRef.current is not None {
                elementRef.current.removeEventListener(eventType, eventHandler);
            }
        };
    }, [eventType, disabled]);
    return elementRef;
}

