import from "react" { createContext, useContext }
import from "@radix-ui/react-toggle-group" { * as ToggleGroupPrimitive }
import from "@/lib/utils" { cn }
import from "@/components/ui/toggle" { toggleVariants }

glob ToggleGroupContext = createContext({"size": "default", "variant": "default"});

def:pub ToggleGroup(
    className: str = "",
    variant: str = "default",
    size: str = "default",
    children: object = None,
    ref: Ref[HTMLElement] = Ref(),
    rest: dict[str, object] = {}
) -> JsxElement {
    <ToggleGroupPrimitive.Root
        ref={ref}
        className={cn("flex items-center justify-center gap-1", className)}
        {**rest}
    >
        <ToggleGroupContext.Provider value={{"variant": variant, "size": size}}>
            {children}
        </ToggleGroupContext.Provider>
    </ToggleGroupPrimitive.Root>
}

def:pub ToggleGroupItem(
    className: str = "",
    children: object = None,
    variant: str = "default",
    size: str = "default",
    ref: Ref[HTMLElement] = Ref(),
    rest: dict[str, object] = {}
) -> JsxElement {
    context = useContext(ToggleGroupContext);
    resolved_variant = context["variant"] or variant if context else variant;
    resolved_size = context["size"] or size if context else size;
    variant_cls = toggleVariants.call(None, {"variant": resolved_variant, "size": resolved_size});
    <ToggleGroupPrimitive.Item
        ref={ref}
        className={cn(variant_cls, className)}
        {**rest}
    >
        {children}
    </ToggleGroupPrimitive.Item>
}

