def:pub createFontLinkTags(
    fontName: str,
    newChars: list[str],
    display: Display,
    onLoad: Callable[[], None] | None = None,
    fontWeights: FontWeights | None = None,
) -> list[JsxElement] {
    requestItalic = False;
    if fontWeights {
        for weight in fontWeights {
            if isinstance(weight, list) and len(weight) == 2 and weight[0] == "ital" {
                requestItalic = True;
                break;
            }
        }
    }
    requestWeights = fontWeights is not None;

    batches: list[set[str]] = [];
    batchSize = 200;
    currentBatch: set[str] = set();

    for char in newChars {
        currentBatch.add(char);
        if len(currentBatch) == batchSize {
            batches.append(currentBatch);
            currentBatch = set();
        }
    }
    if len(currentBatch) > 0 {
        batches.append(currentBatch);
    }

    styleSpec = "";
    if requestItalic {
        styleSpec = ":ital";
    }
    if requestWeights {
        weights = fontWeights as FontWeights;
        if requestItalic {
            styleSpec += f",wght@{getWeights(weights)}";
        } else {
            styleSpec += f":wght@{getWeights(weights)}";
        }
    }

    familyName = re.sub(r"\s", "+", fontName);
    links: list[JsxElement] = [];
    for (index, batch) in enumerate(batches) {
        encodedText = encodeURIComponent("".join(list(batch)));
        url = f"https://fonts.googleapis.com/css2?family={familyName}{styleSpec}&text={encodedText}&display={display}";
        keyVal = encodedText[:10];
        if onLoad and index == len(batches) - 1 {
            links.append(<link rel="stylesheet" href={url} key={keyVal} onLoad={onLoad} />);
        } else {
            links.append(<link rel="stylesheet" href={url} key={keyVal} />);
        }
    }
