import { Box, Drawer } from "@mui/material";
import React from "react";

import SideNavContent from "./SideNavContent";

export default function SideNav({
  sx,
  drawerPaperSx,
  direction,
  mobileOpen,
  handleDrawerToggle,
}) {
  return (
    <Box component="nav" sx={sx}>
      <Box sx={{ display: { xs: "block", sm: "none" } }}>
        <Drawer
          variant="temporary"
