    return units * interval;
}

glob DAY_MAP: dict[str, int] = {"SU": 0, "MO": 1, "TU": 2, "WE": 3, "TH": 4, "FR": 5, "SA": 6};

def advanceDate(date: object, frequency: str, interval: int) -> object {
    switch frequency {
        case "DAILY":
            return addDays(date, interval);
        case "WEEKLY":
            return addWeeks(date, interval);
        case "MONTHLY":
            return addMonths(date, interval);
        case "YEARLY":
            return addYears(date, interval);
