import re;

def:pub template(source: str, data: dict[str, str] | None = None) -> str {
    if data is None {
        return source;
    }
    result = source;
    for (k, v) in data.items() {
        pattern = re.compile(f"{{\\s*{re.escape(k)}\\s*}}");
        result = pattern.sub(v, result);
    }
    return result;
}

