import from "@/shared/types" { BookmarkNodesAction, BookmarkNodesState }
import from .getNode { getNode }

def:pub onNodeChanged(state: BookmarkNodesState, action: BookmarkNodesAction) -> BookmarkNodesState {
    data = action.get("data");
    if not data or not isinstance(data, dict) {
        return state;
    }
    nodeId = data["id"] as str;
    existingNode = getNode(state, nodeId);
    mergedNode = dict(existingNode);
    for (k, v) in data.items() {
        mergedNode[k] = v;
    }
    newData = dict(state["data"]);
    newData[nodeId] = mergedNode;
    newState = dict(state);
    newState["data"] = newData;
    return newState as BookmarkNodesState;
}

