async def request[T](params: RequestParams) -> T {
    url = params.url;
    method = params.method;
    options = params.options;
    request_headers = Headers();
    token = await getToken();
    if not isMockApi() {
        if not token {
            raise Exception("Authentication token is not available");
        }
        request_headers.set("Authorization", f"Bearer {token}");
    }
    if options is not None and options.body is not None {
        request_headers.set("Content-Type", "application/json");
    }
    fetch_options: dict[str, object] = {"method": method, "headers": request_headers};
    if options is not None and options.body is not None {
        fetch_options["body"] = options.body;
    }
    response = await fetch(url, fetch_options);
    if not response.ok {
        raise Exception(f"API error with status code {response.status}: {response.statusText}");
    }
    content_type = response.headers.get("content-type");
    if content_type is not None and "application/json" in content_type {
        return await response.json() as T;
    }
    return {} as T;
}

