glob _BUTTON_VARIANT_CLASSES: dict[str, str] = {
    "default": "bg-primary text-primary-foreground hover:bg-primary/80",
    "outline": "border-border bg-input/30 hover:bg-input/50 hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground",
    "secondary": "bg-secondary text-secondary-foreground hover:bg-secondary/80 aria-expanded:bg-secondary aria-expanded:text-secondary-foreground",
    "ghost": "hover:bg-muted hover:text-foreground dark:hover:bg-muted/50 aria-expanded:bg-muted aria-expanded:text-foreground",
    "destructive": "bg-destructive/10 hover:bg-destructive/20 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/20 text-destructive focus-visible:border-destructive/40 dark:hover:bg-destructive/30",
    "link": "text-primary underline-offset-4 hover:underline"
};

glob _BUTTON_SIZE_CLASSES: dict[str, str] = {
    "default": "h-9 gap-1.5 px-3 has-data-[icon=inline-end]:pr-2.5 has-data-[icon=inline-start]:pl-2.5",
    "xs": "h-6 gap-1 px-2.5 text-xs has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2 [&_svg:not([class*='size-'])]:size-3",
    "sm": "h-8 gap-1 px-3 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
    "lg": "h-10 gap-1.5 px-4 has-data-[icon=inline-end]:pr-3 has-data-[icon=inline-start]:pl-3",
    "icon": "size-9",
    "icon-xs": "size-6 [&_svg:not([class*='size-'])]:size-3",
    "icon-sm": "size-8",
    "icon-lg": "size-10"
};

glob _BUTTON_EXCLUDE_KEYS: list[str] = ["className", "variant", "size", "asChild", "children"];

def _resolve_button_class(variant: str, size: str, className: str = "") -> str {
    variantClass = _BUTTON_VARIANT_CLASSES.get(variant);
    if not variantClass {
        variantClass = _BUTTON_VARIANT_CLASSES["default"];
    }
    sizeClass = _BUTTON_SIZE_CLASSES.get(size);
    if not sizeClass {
        sizeClass = _BUTTON_SIZE_CLASSES["default"];
    }
    return cn(_BUTTON_BASE, variantClass, sizeClass, className);
}

def:pub buttonVariants(opts: dict[str, object] = {}) -> str {
    variant = opts["variant"];
    if not variant {
        variant = "default";
    }
    size = opts["size"];
    if not size {
        size = "default";
    }
    extra = opts["className"];
    if not extra {
        extra = "";
    }
    return _resolve_button_class(variant as str, size as str, extra as str);
}

def:pub Button(props: dict[str, object]) -> JsxElement {
    variant = props["variant"];
    if not variant {
        variant = "default";
    }
    size = props["size"];
    if not size {
        size = "default";
    }
    asChild = props["asChild"];
    if not asChild {
        asChild = False;
    }
    restProps: dict[str, object] = {};
    for key in Object.keys(props) {
        if key not in _BUTTON_EXCLUDE_KEYS {
            restProps[key] = props[key];
        }
    }
    computedClass = cn(buttonVariants({"variant": variant, "size": size, "className": props["className"]}));

    if asChild {
        return
            <Slot.Root
                data-slot="button"
                data-variant={variant}
                data-size={size}
                className={computedClass}
                {**restProps}
            >
                {props["children"]}
            </Slot.Root>;
    }

    <button
        data-slot="button"
        data-variant={variant}
        data-size={size}
        className={computedClass}
        {**restProps}
    >
        {props["children"]}
    </button>
}

