import from database.models.file { File }

obj FileResponse {
    has file_id: str;
    has subject_id: str;
    has filename: str;
    has filepath: str;
}

obj FileUpdateData {
    has filename: str | None = None;
    has filepath: str | None = None;
}

def toFileResponse(file: File) -> FileResponse {
    data = file.toJSON();
    return FileResponse(
        file_id=data["file_id"] as str,
        subject_id=data["subject_id"] as str,
        filename=data["filename"] as str,
        filepath=data["filepath"] as str,
    );
}

obj FileService {
    static async def createFile(
        fileId: str,
        subjectId: str,
        filename: str,
        filepath: str,
    ) -> FileResponse {
        file = await File.create(
            file_id=fileId,
            subject_id=subjectId,
            filename=filename,
            filepath=filepath,
        );
        return toFileResponse(file);
    }

    static async def getFiles(subjectId: str | None = None) -> list[FileResponse] {
        where: dict[str, str] = {};
        if subjectId is not None {
            where["subject_id"] = subjectId;
        }
        files = await File.findAll(where=where);
        return [toFileResponse(file) for file in files];
    }

    static async def getFile(fileId: str) -> FileResponse | None {
        file = await File.findByPk(fileId);
        if file is None {
            return None;
        }
        return toFileResponse(file);
    }

    static async def updateFile(fileId: str, updates: FileUpdateData) -> bool {
        updateData: dict[str, str] = {};
        if updates.filename is not None {
            updateData["filename"] = updates.filename;
        }
