import re;

def removeImages(content: str) -> str {
    return re.sub(r'!\[\[.*?\]\]', '', content);
}

def removeHyperlinks(content: str) -> str {
    return re.sub(r'\[(.*?)\]\((.*?)\)', r'\1', content);
}

def removeCitations(content: str) -> str {
    return re.sub(r'\[\d+\]', '', content);
}

def splitText(text: str) -> list[str] {
    cleanedText: str = re.sub(r'\n', ' ', text);
    cleanedText = re.sub(r'\s+', ' ', cleanedText);
    cleanedText = removeCitations(cleanedText);
    cleanedText = removeHyperlinks(cleanedText);
    cleanedText = removeImages(cleanedText);

    if '.' in cleanedText {
        sentenceRegex = r'(?<!\w\.\w)(?<![A-Z][a-z]\.)(?<=[.!?])\s+(?=[A-Z])';
        return re.split(sentenceRegex, cleanedText);
    }

    chunkSize: int = 6000;
    return [
        cleanedText[i:i + chunkSize]
        for i in range(0, len(cleanedText), chunkSize)
    ];
}

