glob:pub CREDENTIALS_SEPERATOR = ":";

def buildStorageCredentials(username: str, password: str) -> str {
    return f"{username}{CREDENTIALS_SEPERATOR}{password}";
}

class:pub StorageAuth {
    has username: str = "";
    has password: str = "";
    has isAuthenticated: bool = False;

    def init(credentials: str) {
        parts = credentials.split(CREDENTIALS_SEPERATOR);
        self.username = parts[0] if len(parts) > 0 else "";
        self.password = parts[1] if len(parts) > 1 else "";
        self.isAuthenticated = bool(self.username and self.password);
    }

    def getUsername() -> str {
        return self.username;
    }

    def getPassword() -> str {
        return self.password;
    }

    def setUsername(username: str) {
        self.username = username;
    }

    def setPassword(password: str) {
        self.password = password;
    }

    def getIsAuthenticated() -> bool {
        return self.isAuthenticated;
    }

    def persistToStorage(remember: bool) {
        credentials = buildStorageCredentials(self.username, self.password);
        if remember {
            localStorage.setItem(STORAGE_KEY, credentials);
            sessionStorage.removeItem(STORAGE_KEY);
        } else {
            localStorage.removeItem(STORAGE_KEY);
            sessionStorage.setItem(STORAGE_KEY, credentials);
        }
    }

    def clear() {
        localStorage.removeItem(STORAGE_KEY);
        sessionStorage.removeItem(STORAGE_KEY);
    }
}

js:
export const STORAGE_KEY = 'miab-cp-credentials';
export const CREDENTIALS_SEPERATOR = ':';

function buildStorageCredentials(username: string, password: string): string {
  return `${username}${CREDENTIALS_SEPERATOR}${password}`;
}

export class StorageAuth {
  private username: string;
  private password: string;
  private isAuthenticated = false;
  constructor(private readonly credentials: string) {
    const [username = '', password = ''] = this.credentials.split(
      CREDENTIALS_SEPERATOR
    );
    this.username = username;
    this.password = password;
    this.isAuthenticated = Boolean(username && password);
  }

  getUsername(): string {
    return this.username;
  }

  getPassword(): string {
    return this.password;
  }

  setUsername(username: string): void {
    this.username = username;
  }

  setPassword(password: string): void {
    this.password = password;
  }

  getIsAuthenticated(): boolean {
    return this.isAuthenticated;
  }

  persistToStorage(remember: boolean): void {
    const credentials = buildStorageCredentials(this.username, this.password);
    if (remember) {
      localStorage.setItem(STORAGE_KEY, credentials);
      sessionStorage.removeItem(STORAGE_KEY);
    } else {
      localStorage.removeItem(STORAGE_KEY);
      sessionStorage.setItem(STORAGE_KEY, credentials);
    }
  }

  clear(): void {
    localStorage.removeItem(STORAGE_KEY);
    sessionStorage.removeItem(STORAGE_KEY);
  }
}

