glob RULE_ID = "contents-no-position";

def warn(fields: dict[str, str]) -> Warning {
    return createWarning(RULE_ID, fields);
}

glob SUGGESTION = "Remove this property, or change display to a value that generates a box (e.g. block, flex).";

glob OFFSET_PROPERTIES: list[str] = ["top", "right", "bottom", "left"];

glob LOGICAL_OFFSET_PROPERTIES: list[dict[str, str]] = [
    {"key": "insetBlockStart", "cssName": "inset-block-start"},
    {"key": "insetBlockEnd", "cssName": "inset-block-end"},
    {"key": "insetInlineStart", "cssName": "inset-inline-start"},
    {"key": "insetInlineEnd", "cssName": "inset-inline-end"},
