glob TABLE_PROPERTIES: list[dict[str, str | bool]] = [
    {"key": "borderCollapse", "cssName": "border-collapse", "defaultValue": "separate", "inherited": True},
    {"key": "tableLayout", "cssName": "table-layout", "defaultValue": "auto", "inherited": False},
