import from "react" { useState, useEffect }

obj OptimisticUIState[T] {
    has status: str;
    has result: T | None = None;
    has error: Exception | None = None;
}

def:pub useOptimisticUI[T](func: Callable[[], Awaitable[T]], predictedResult: T) -> OptimisticUIState[T] {
    statusRef = useState("pending");
    status = statusRef[0] as str;
    setStatus = statusRef[1];
    resultRef = useState(predictedResult);
    result = resultRef[0] as T | None;
    setResult = resultRef[1];
    errorRef = useState(None);
    error = errorRef[0] as Exception | None;
    setError = errorRef[1];
    useEffect(lambda {
        async def invokeFunction() {
            setStatus("loading");
            try {
                fetched = await func();
                setStatus("succeed");
                setResult(fetched);
            } except Exception as caught {
                setStatus("failed");
                setError(caught);
            }
        }
        invokeFunction();
    }, []);
    return OptimisticUIState[T](status=status, result=result, error=error);
}

js:
import { useState, useEffect } from 'react'

interface OptimisticUIState<T> {
  readonly status: 'pending' | 'loading' | 'failed' | 'succeed'
  readonly result?: T
  readonly error?: Error
}

export function useOptimisticUI<T>(
  func: (...args: readonly any[]) => Promise<T>,
  predictedResult: T
): OptimisticUIState<T> {
  const [optimisticUIState, setOptimisticUIState] = useState<
    OptimisticUIState<T>
  >({
    status: 'pending',
    result: predictedResult
  })

  useEffect(() => {
    async function invokeFunction(): Promise<void> {
      setOptimisticUIState({
        ...optimisticUIState,
        status: 'loading'
      })
      try {
        const result: T = await func()
        setOptimisticUIState({
          status: 'succeed',
          result
        })
      } catch (error) {
        setOptimisticUIState({
          ...optimisticUIState,
          status: 'failed',
          error
        })
      }
    }

    invokeFunction()
  }, [])

  return optimisticUIState
}

