glob PADDING_PAIRS: list[{physical: {key: str, cssName: str}, logical: {key: str, cssName: str}}] = [
    {"physical": {"key": "paddingTop", "cssName": "padding-top"}, "logical": {"key": "paddingBlockStart", "cssName": "padding-block-start"}},
    {"physical": {"key": "paddingBottom", "cssName": "padding-bottom"}, "logical": {"key": "paddingBlockEnd", "cssName": "padding-block-end"}},
    {"physical": {"key": "paddingRight", "cssName": "padding-right"}, "logical": {"key": "paddingInlineEnd", "cssName": "padding-inline-end"}},
