def:pub easeInOutQuad(t: float, b: float, c: float, d: float) -> float {
    t /= (d / 2);
    if (t < 1) {
        return (((c / 2) * t) * t) + b;
    }
    t -= 1;
    return (((-c / 2) * ((t * (t - 2)) - 1)) + b);
}

