      <div className='server-name-label'>
        { props.i18n.current.get('server') }: { props.account.host }
      </div>
      <button onClick={ onClickLogout }>
        { props.i18n.current.get('do-logout') }
      </button>
    </div>
  );
};
export default AccountInfo;

