import { Component } from 'react';
import type { ErrorInfo, ReactNode } from 'react';

interface Props {
  children: ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error('[css-noop-checker]', error, info.componentStack);
  }

  render() {
    if (this.state.error) {
      return (
        <div className="panel" style={{ padding: 16, textAlign: 'center' }}>
          <p style={{ color: 'var(--warning-color)', fontWeight: 600 }}>Something went wrong</p>
          <p style={{ color: 'var(--text-muted)', fontSize: 11, marginTop: 4 }}>
            {this.state.error.message}
          </p>
          <button
            type="button"
            className="scan-message__back"
            style={{ marginTop: 8 }}
            onClick={() => this.setState({ error: null })}
          >
            Retry
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

import { container, FactoryProvider, InjectionToken, registry } from 'tsyringe';
import { Merge, Sheet } from './lib/types';
import {
  ConfigService,
  SheetService,
  SheetServiceFactory,
  MergesService,
  MergesServiceFactory,
  CellRange,
  CellRangeFactory,
  Selector,
  SelectorFactory,
  ScrollingService,
  RenderProxyService,
} from './lib/services';

// @registry()
// // eslint-disable-next-line @typescript-eslint/no-unused-vars
// class __Registry__ {}

export * from './lib/crdt/yjs-workbook';
export * from './lib/constants';
export * from './lib/utils';
export * from './lib/types';
export * from './lib/services';
export * from './lib/controllers';

export function createCore() {
  const factoryProviders: Array<
    FactoryProvider<unknown> & { token: InjectionToken }
  > = [
    {
      token: SheetService,
      useFactory:
        (dependencyContainer): SheetServiceFactory =>
        (d: Sheet) =>
          new SheetService(
            d,
            dependencyContainer.resolve(ConfigService),
            dependencyContainer.resolve(ScrollingService),
            dependencyContainer.resolve(RenderProxyService),
            dependencyContainer.resolve(MergesService) as never,
            dependencyContainer.resolve(Selector) as never,
          ),
    },
    {
      token: CellRange,
      useFactory:
        (dependencyContainer): CellRangeFactory =>
        (sri: number, eri: number, sci: number, eci: number) =>
          new CellRange(
            sri,
            eri,
            sci,
            eci,
            dependencyContainer.resolve(ConfigService),
          ),
    },
    {
      token: Selector,
      useFactory:
        (dependencyContainer): SelectorFactory =>
        (sri: number, eri: number, sci: number, eci: number) =>
          new Selector(
            sri,
            eri,
            sci,
            eci,
            dependencyContainer.resolve(CellRange) as never,
          ),
    },
    {
      token: MergesService,
      useFactory:
        (dependencyContainer): MergesServiceFactory =>
        (merges: Merge[]) =>
          new MergesService(
            merges,
            dependencyContainer.resolve(CellRange) as never,
          ),
    },
  ];
  for (const p of factoryProviders) {
    container.register(p.token, p);
  }
}

