    case StatusEntryType.Error:
      return 'Error';
    case StatusEntryType.Warning:
    default:
      return 'Warning';
  }
}

function getIconColor(type: string): string {
  switch (type) {
    case StatusEntryType.Ok:
      return theme.palette.green;
    case StatusEntryType.Error:
      return theme.palette.red;
    case StatusEntryType.Warning:
