obj SubscriptionBag {
    has cleanups: list[Callable[[], None]] = [];

    def add(cleanup: object) {
        if callable(cleanup) {
            self.cleanups.append(cleanup as Callable[[], None]);
        } else {
            unsub_fn = getattr(cleanup, "unsubscribe") as Callable[[], None];
            self.cleanups.append(lambda { unsub_fn(); });
        }
    }

    def cleanup() {
        pending = self.cleanups;
        self.cleanups = [];
        for fn in pending {
            fn();
        }
    }
}

js:
export class SubscriptionBag {
  private cleanups: Array<() => void> = [];

  add(cleanup: { unsubscribe: () => void } | (() => void)): void {
    this.cleanups.push(
      typeof cleanup === 'function' ? cleanup : () => cleanup.unsubscribe(),
    );
  }

  cleanup(): void {
    for (const cleanup of this.cleanups.splice(0)) {
      cleanup();
    }
  }
}

