import from "../env/data" { default as data }

type ValidatorType = "object" | "boolean" | "number" | "function" | "string" | "symbol";
type ValidatorFn = Callable[[object, str, dict[str, object]], bool];
type TypeCheckResult = bool | str;

glob VERSION: str = (data as dict[str, str])["version"];

glob deprecatedWarnings: dict[str, bool] = {};

def js_typeof(value: object) -> str {
    if value is None {
        return "object";
    }
    if isinstance(value, bool) {
        return "boolean";
    }
    if isinstance(value, int) or isinstance(value, float) {
        return "number";
    }
    if isinstance(value, str) {
        return "string";
    }
    if callable(value) {
        return "function";
    }
    return "object";
}

def validator(type: ValidatorType, thing: object, isAn: bool = False) -> TypeCheckResult {
    if js_typeof(thing) == type {
        return True;
    }
    article = "n " if isAn else " ";
    return "a" + article + type;
}

def format_transitional_message(opt: str, desc: str, message: str | None) -> str {
    extra = ". " + message if message is not None else "";
    return "[Axios v" + VERSION + "] Transitional option '" + opt + "'" + desc + extra;
}

def make_transitional(
    validator_param: ValidatorFn | bool,
    version: str | None = None,
    message: str | None = None
) -> ValidatorFn {
    def inner(value: object, opt: str, opts: dict[str, object]) -> bool {
        if validator_param is False {
            removed = " in " + version if version is not None else "";
            raise ValueError(format_transitional_message(opt, " has been removed" + removed, message));
        }
        if version is not None and opt not in deprecatedWarnings {
            deprecatedWarnings[opt] = True;
            print(format_transitional_message(
                opt,
                " has been deprecated since v" + version + " and will be removed in the near future",
                message
            ));
        }
        if isinstance(validator_param, bool) {
            return True;
        }
        return validator_param(value, opt, opts);
    }
    return inner;
}

obj Validators {
    def transitional(
        validator_param: ValidatorFn | bool,
        version: str | None = None,
        message: str | None = None
    ) -> ValidatorFn {
        return make_transitional(validator_param, version, message);
    }
    def object(thing: object) -> TypeCheckResult {
        return validator("object", thing, True);
    }
    def boolean(thing: object) -> TypeCheckResult {
        return validator("boolean", thing);
    }
    def number(thing: object) -> TypeCheckResult {
        return validator("number", thing);
    }
    def function(thing: object) -> TypeCheckResult {
        return validator("function", thing);
    }
    def string(thing: object) -> TypeCheckResult {
        return validator("string", thing);
    }
    def symbol(thing: object) -> TypeCheckResult {
        return validator("symbol", thing);
    }
}

glob validators: Validators = Validators();

def assertOptions(
    options: dict[str, object],
    schema: dict[str, ValidatorFn],
    allowUnknown: bool = False
) {
    if not isinstance(options, dict) {
        raise TypeError("options must be an object");
    }
    for opt in options {
        if opt in schema {
            schema_validator = schema[opt];
            value = options[opt];
            result = value is None or schema_validator(value, opt, options);
            if result is not True {
                raise TypeError("option " + opt + " must be " + str(result));
            }
            continue;
        }
        if not allowUnknown {
            raise Exception("Unknown option " + opt);
        }
    }
}

obj ValidatorDefault {
    has assertOptions: Callable[[dict[str, object], dict[str, ValidatorFn], bool], None];
    has validators: Validators;
}

glob:pub default: ValidatorDefault = ValidatorDefault(
    assertOptions=assertOptions,
    validators=validators,
);

