import from urllib.parse { quote }
import from datetime { datetime }
import from ..utils { forEach, isURLSearchParams, isArray, isDate, isObject }

def encode(val: str | int | bool) -> str {
    s = quote(str(val), safe="");
    s = s.replace("%3A", ":");
    s = s.replace("%24", "$");
    s = s.replace("%2C", ",");
    s = s.replace("%20", "+");
    s = s.replace("%5B", "[");
    s = s.replace("%5D", "]");
    return s;
}

def encodeValue(v: object) -> str | int | bool {
    if isDate(v) {
        return (v as datetime).isoformat();
    }
    if isObject(v) {
        import json;
        return json.dumps(v);
    }
    return v as str | int | bool;
}

def serializeParams(params: dict[str, object], parts: list[str]) {
    forEach(params, lambda (val: object, key: str) {
        if val is None {
            return;
        }
        serializedKey = key;
        values: list[object];
        if isArray(val) {
            serializedKey = key + "[]";
            values = val as list[object];
        } else {
            values = [val];
        }
        forEach(values, lambda (v: object) {
            parts.append(encode(serializedKey) + "=" + encode(encodeValue(v)));
        });
    });
}

def buildURL(
    url: str = "",
    params: object | None = None,
    paramsSerializer: Callable[[object], str] | None = None
) -> str {
    if not params {
        return url;
    }
    serializedParams: str = "";
    if paramsSerializer {
        serializedParams = paramsSerializer(params);
    } elif isURLSearchParams(params) {
        serializedParams = str(params);
    } else {
        parts: list[str] = [];
        serializeParams(params as dict[str, object], parts);
        serializedParams = "&".join(parts);
    }
    if serializedParams {
        hashmarkIndex = url.find("#");
        if hashmarkIndex != -1 {
            url = url[:hashmarkIndex];
        }
        url += ("?" if "?" not in url else "&") + serializedParams;
    }
    return url;
}

