          {/* Tooltip arrow */}
          <div className="absolute left-full top-1/2 -translate-y-1/2 border-l-4 border-l-gray-800/90 border-y-4 border-y-transparent"></div>
        </motion.div>
      </div>
    </motion.div>
  );
}

