import from datetime { datetime }

type Cell = str | int | float | None;
type Field = str;

def:pub toTimeSeries(
    rows: list[list[Cell]],
    fields: list[Field],
    field: Field,
) -> list[tuple[Cell, Cell]] {
    dateIdx = fields.index("date");
    valueIdx = fields.index(field);
    return [
        (row[dateIdx], row[valueIdx])
        for row in rows
        if isinstance(row[valueIdx], (int, float))
    ];
}

glob MS_PER_DAY: int = 86400000;

def:pub toIndexedSeries(
    rows: list[list[Cell]],
    fields: list[Field],
    field: Field,
) -> list[tuple[int, Cell]] {
    dateIdx = fields.index("date");
    valueIdx = fields.index(field);
    if len(rows) == 0 {
        return [];
    }
    firstDate = rows[0][dateIdx];
    if not isinstance(firstDate, str) {
        return [];
    }
    firstParsed = datetime.fromisoformat(firstDate);
    result: list[tuple[int, Cell]] = [];
    for row in rows {
        if not isinstance(row[valueIdx], (int, float)) {
            continue;
        }
        date = row[dateIdx];
        dayOffset = 0;
        if isinstance(date, str) {
            deltaMs = (datetime.fromisoformat(date) - firstParsed).total_seconds() * 1000;
            dayOffset = round(deltaMs / MS_PER_DAY);
        }
        result.append((dayOffset, row[valueIdx]));
    }
    return result;
}

def:pub sliceSeriesUpTo(series: list[tuple[Cell, Cell]], asOfDate: str) -> list[tuple[Cell, Cell]] {
    return [
        pair
        for pair in series
        if isinstance(pair[0], str) and pair[0] <= asOfDate
    ];
}

