obj _NumberFormatter {
    has locale: str;
    has compact: bool = False;

    def format(value: float) -> str {
        if self.compact {
            abs_val = abs(value);
            if abs_val >= 1_000_000_000 {
                scaled = value / 1_000_000_000;
                suffix = "mil millones" if self.locale.startswith("es") else "billion";
                return f"{scaled:.1f} {suffix}";
            }
            if abs_val >= 1_000_000 {
                scaled = value / 1_000_000;
                suffix = "millones" if self.locale.startswith("es") else "million";
                return f"{scaled:.1f} {suffix}";
            }
            if abs_val >= 1_000 {
                scaled = value / 1_000;
                suffix = "mil" if self.locale.startswith("es") else "thousand";
                return f"{scaled:.1f} {suffix}";
            }
        }
        if value == int(value) {
            return f"{int(value):,}";
        }
        return f"{value:,.2f}";
    }
}

glob _numberFormatters: dict[str, _NumberFormatter] = {};
glob _compactFormatters: dict[str, _NumberFormatter] = {};

def getNumberFormatter(locale_name: str) -> _NumberFormatter {
    cached = _numberFormatters.get(locale_name);
    if cached is not None {
        return cached;
    }
    formatter = _NumberFormatter(locale=locale_name, compact=False);
    _numberFormatters[locale_name] = formatter;
    return formatter;
}

def getCompactFormatter(locale_name: str) -> _NumberFormatter {
    cached = _compactFormatters.get(locale_name);
    if cached is not None {
        return cached;
    }
    formatter = _NumberFormatter(locale=locale_name, compact=True);
    _compactFormatters[locale_name] = formatter;
    return formatter;
}

def:pub formatDate(isoDate: str | None, lang: str = "es") -> str {
    if not isoDate {
        return "—";
    }
    parts = isoDate.split("-");
    year = int(parts[0]);
    month = int(parts[1]);
    day = int(parts[2]);
    monthName = MONTHS[lang][month - 1] if month else None;
    if (not year) or (not day) or (monthName is None) {
        return isoDate;
    }
    return f"{monthName} {day}, {year}" if lang == "en" else f"{day} {monthName} {year}";
}

