class UserRepository(MongooseAbstractRepository) {
    def init() {
        super().__init__("User", "USchema");
    }

    async def findOneAndUpdate(_id: str, userUpdatesObj: IUser) -> IUser {
        oldObj = await super().findByQuery({}) as IUser | None;
        if not oldObj {
            raise ValueError("User cannot be null");
        }
        oldId = oldObj["_id"];
        if oldId {
            merged: IUser = {**oldObj, **userUpdatesObj} as IUser;
            return await super().findOneAndUpdate(str(_id), merged, True) as IUser;
        }
        return oldObj;
    }
}

