import from "react" { useMemo }

type CssProperties = dict[str, str | float | int];

def calc_z_index(viewState: dict[str, object]) -> int {
    if viewState["kind"] == "maximized" {
        return 9999;
    }
    if viewState["kind"] == "open" {
        return 1000 + (viewState["viewStackOrder"] as int);
    }
    return 0;
}

def should_disable_filter(viewState: dict[str, object]) -> bool {
    if viewState["kind"] == "open" and viewState["isActive"] {
        return True;
    }
    if viewState["kind"] == "maximized" {
        return True;
    }
    return False;
}

def:pub useWindowStyle(
    x: float,
    y: float,
    width: float,
    height: float,
    viewState: dict[str, object],
    desktopRect: dict[str, float] | None,
    style: CssProperties | None = None,
    isDragging: bool = False,
    isResizing: bool = False
) -> CssProperties {
    return useMemo(lambda {
        baseStyle: CssProperties = {
            "position": "absolute",
            "left": 0 if viewState["kind"] == "maximized" else x,
            "top": 0 if viewState["kind"] == "maximized" else y,
            "width": desktopRect["width"] if viewState["kind"] == "maximized" and desktopRect else width,
            "height": desktopRect["height"] if viewState["kind"] == "maximized" and desktopRect else height,
            "zIndex": calc_z_index(viewState),
            "display": "flex",
            "flexDirection": "column",
            "boxSizing": "border-box"
        };
        if not (isDragging or isResizing) {
            baseStyle["transition"] = "all 0.2s ease-in-out, opacity 0.3s ease-in-out";
        }
        if style {
            baseStyle = {**baseStyle, **style};
        }
        if viewState["kind"] == "minimized" {
            baseStyle["transform"] = "scale(0)";
            baseStyle["opacity"] = 0;
            baseStyle["pointerEvents"] = "none";
        }
        baseStyle["filter"] = "none" if should_disable_filter(viewState) else "grayscale(100%)";
        baseStyle;
    }, [x, y, width, height, viewState, desktopRect, style, isDragging, isResizing]);
}

