import from "./dictionary" { default as dictionary }

def lookup_message(data: dict[str, object], key: str, fallback: str) -> str {
    current: object = data;
    for part in key.split(".") {
        if isinstance(current, dict) and part in current {
            current = current[part];
        } else {
            return fallback;
        }
    }
    if isinstance(current, str) {
        return current;
    }
    return fallback;
}

obj Logger {
    static def getMessage(key: str) -> str {
        message = lookup_message(dictionary as dict[str, object], key, "Invalid error key");
        return "react-registry - " + message;
    }

    static def throw(key: str) {
        raise Exception(Logger.getMessage(key));
    }

    static def error(key: str) {
        message = "Error: " + Logger.getMessage(key);
        if message {
            console.error(message);  # jac:ignore[E1032]
        }
    }

    static def warn(key: str) {
        message = "Warning: " + Logger.getMessage(key);
        if message {
            console.warn(message);  # jac:ignore[E1032]
        }
    }
}

