import from datetime { datetime }

def isSubset(superSet: object, subSet: object) -> bool {
    if superSet is None or subSet is None {
        return False;
    }
    if isinstance(superSet, datetime) or isinstance(subSet, datetime) {
        if isinstance(superSet, datetime) and isinstance(subSet, datetime) {
            return superSet.timestamp() == subSet.timestamp();
        }
        return False;
    }
    if not isinstance(superSet, dict) or not isinstance(subSet, dict) {
        return False;
    }
    super_dict = superSet as dict[str, object];
    sub_dict = subSet as dict[str, object];
    for key in sub_dict {
        if key not in super_dict {
            return False;
        }
        sub_item = sub_dict[key];
        super_item = super_dict[key];
        if isinstance(sub_item, (dict, list)) {
            if not isSubset(super_item, sub_item) {
                return False;
            }
        } elif super_item != sub_item {
            return False;
        }
    }
    return True;
}

