glob:pub GRID_SIZE_X: int = 100;

glob:pub GRID_SIZE_Y: int = 120;

glob:pub ICON_WIDTH: int = 96;

glob:pub ICON_HEIGHT: int = 112;

def:pub snapToGrid(position: Point) -> Point {
    return Point(
        x=float(round(position.x / GRID_SIZE_X)) * GRID_SIZE_X,
        y=float(round(position.y / GRID_SIZE_Y)) * GRID_SIZE_Y
    );
