def:pub getGridOffset(position: Point) -> Point {
    snapped = snapToGrid(position);
    return Point(x=snapped.x - position.x, y=snapped.y - position.y);
}

def doIconsOverlap(pos1: Point, pos2: Point) -> bool {
    return (
        (pos1.x < pos2.x + ICON_WIDTH)
        and (pos1.x + ICON_WIDTH > pos2.x)
        and (pos1.y < pos2.y + ICON_HEIGHT)
        and (pos1.y + ICON_HEIGHT > pos2.y)
    );
}

def:pub findNearestAvailablePosition(
    desiredPosition: Point,
    occupiedPositions: list[OccupiedIcon],
    containerWidth: float,
    containerHeight: float,
    excludeIds: list[str] | None = None
) -> Point {
    ids = excludeIds if excludeIds is not None else [];
    snappedDesired = snapToGrid(desiredPosition);
    relevantOccupied = [p for p in occupiedPositions if p.id not in ids];
    hasOverlap = False;
    for occupied in relevantOccupied {
        if doIconsOverlap(snappedDesired, occupied.position) {
            hasOverlap = True;
            break;
        }
    }
    if not hasOverlap {
        return snappedDesired;
    }
    maxCols = int(floor(containerWidth / GRID_SIZE_X));
    maxRows = int(floor(containerHeight / GRID_SIZE_Y));
    desiredGridX = int(round(snappedDesired.x / GRID_SIZE_X));
    desiredGridY = int(round(snappedDesired.y / GRID_SIZE_Y));
    limit = max(maxCols, maxRows);
    for radius = 1 while radius < limit with radius += 1 {
        for dx = -radius while dx <= radius with dx += 1 {
            for dy = -radius while dy <= radius with dy += 1 {
                if (abs(dx) != radius) and (abs(dy) != radius) {
                    continue;
                }
                gridX = desiredGridX + dx;
                gridY = desiredGridY + dy;
                if gridX < 0 or gridY < 0 or gridX >= maxCols or gridY >= maxRows {
                    continue;
                }
                candidatePos = Point(x=float(gridX * GRID_SIZE_X), y=float(gridY * GRID_SIZE_Y));
                overlaps = False;
                for occupied in relevantOccupied {
                    if doIconsOverlap(candidatePos, occupied.position) {
                        overlaps = True;
                        break;
                    }
                }
                if not overlaps {
                    return candidatePos;
                }
            }
        }
    }
    return snappedDesired;
}

