type FieldOptionEntry = {"label": str, "value": str | int | float | bool};

type FieldOptionsDict = dict[str, str | list[FieldOptionEntry] | None];

def capitalize_first(value: str) -> str {
    if len(value) == 0 {
        return value;
    }
    return value[0].upper() + value[1:];
}

def handleZodString(fieldOptions: FieldOptionsDict) -> FieldOptionsDict {
    return {**fieldOptions, "type": fieldOptions?["type"] or "text"};
}

def handleZodNumber(fieldOptions: FieldOptionsDict) -> FieldOptionsDict {
    return {
        **fieldOptions,
        "inputMode": fieldOptions?["inputMode"] or "numeric",
        "type": fieldOptions?["type"] or "number",
    };
}

def handleZodBoolean(fieldOptions: FieldOptionsDict) -> FieldOptionsDict {
    return {**fieldOptions, "type": fieldOptions?["type"] or "checkbox"};
}

def handleZodEnum(fieldOptions: FieldOptionsDict, fieldValue: ZodEnum) -> FieldOptionsDict {
    options: list[FieldOptionEntry] = [
        {"label": capitalize_first(value), "value": value}
        for value in fieldValue._def.values
    ];
    existing_options = fieldOptions?["options"];
    merged_options = options if existing_options is None else existing_options as list[FieldOptionEntry];
    if fieldOptions?["tag"] == "select" {
        return {
            **fieldOptions,
            "options": merged_options,
            "type": fieldOptions?["type"] or "select",
        };
    }
    return {
        **fieldOptions,
        "type": fieldOptions?["type"] or "checkbox",
        "options": merged_options,
    };
}

def handleNativeZodEnum(fieldOptions: FieldOptionsDict, fieldValue: ZodNativeEnum) -> FieldOptionsDict {
    options: list[FieldOptionEntry] = [
        {"label": capitalize_first(key), "value": value}
        for (key, value) in fieldValue._def.values.items()
    ];
    existing_options = fieldOptions?["options"];
    merged_options = options if existing_options is None else existing_options as list[FieldOptionEntry];
    if fieldOptions?["tag"] == "select" {
        return {**fieldOptions, "options": merged_options};
    }
    return {
        **fieldOptions,
        "type": fieldOptions?["type"] or "checkbox",
        "options": merged_options,
    };
}

