import from "@styled-system/theme-get" { themeGet }
import from "styled-system" { ResponsiveValue }
import from "../components" { BoxProps }
import from "./useTheme" { useTheme }

obj ColorSchemeOptions {
    has colorScheme: str;
    has shading: int | None = None;
    has fallback: str | None = None;
}

def isMultipleOptions(options: ColorSchemeOptions | list[ColorSchemeOptions]) -> bool {
    return isinstance(options, list);
}

def resolveColorSchemeOption(option: ColorSchemeOptions, theme: object) -> str {
    path = f"colors.{option.colorScheme}.{option.shading}";
    return themeGet(path, option.fallback)({"theme": theme});
}

def:pub useColorScheme(options: ColorSchemeOptions | list[ColorSchemeOptions]) -> ResponsiveValue {
    theme = useTheme();
    if isMultipleOptions(options) {
        opts_list = options as list[ColorSchemeOptions];
        return [resolveColorSchemeOption(opt, theme) for opt in opts_list];
    }
    single = options as ColorSchemeOptions;
    return resolveColorSchemeOption(single, theme);
}

def:pub useMultipleColorScheme(mapping: dict[str, ColorSchemeOptions | list[ColorSchemeOptions] | None]) -> dict[str, ResponsiveValue] {
    theme = useTheme();
    result: dict[str, ResponsiveValue] = {};
    for prop in mapping {
        value = mapping[prop];
        if value is None { continue; }
        if isMultipleOptions(value) {
            opts_list = value as list[ColorSchemeOptions];
            result[prop] = [resolveColorSchemeOption(opt, theme) for opt in opts_list];
        } else {
            opt = value as ColorSchemeOptions;
            result[prop] = resolveColorSchemeOption(opt, theme);
        }
    }
    return result;
