export const uuid = (): string => {
  const _p8 = (s?: boolean): string => {
    const p = `${Math.random().toString(16)}000000000`.substr(2, 8)
    return s ? `-${p.substr(0, 4)}-${p.substr(4, 4)}` : p
  }
  return _p8() + _p8(true) + _p8(true) + _p8()
}

