def Segment(active: bool, color: str, size: int, id: str, skew: bool) -> JsxElement | None {
    style_map = skewedSegmentStyle if skew else segmentStyle;
    if id not in style_map {
        console.error(f"react-7-segment-display: Segment style for id \"{id}\" not found.");
        return None;
    }
    ss = style_map[id] as dict[str, object];
    id_val = ss["id"] if "id" in ss else None;
    position_val = "absolute" if id_val else "relative";
    margin_top = ss["marginTop"] as float;
    margin_left = ss["marginLeft"] as float;
    outer_style = {
        "filter": f"drop-shadow(0px 0px {size * 0.3}px {color})" if active else "none",
        "padding": size * 0.3,
        "width": "fit-content",
        "position": position_val,
        "transform": ss["transform"],
        "marginTop": f"{size * margin_top}px",
        "marginLeft": f"{size * margin_left}px",
        "zIndex": "2",
    };
    inner_style = {
        "backgroundColor": color,
        "filter": "opacity(1) grayscale(0)" if active else "opacity(0.3) grayscale(0.7)",
        "color": color,
        "clipPath": ss["clipPath"],
        "WebkitClipPath": ss["clipPath"],
        "MozClipPath": ss["clipPath"],
        "height": f"{size}px",
        "width": f"{size * 5}px",
    };
    <div style={outer_style}><div style={inner_style}></div></div>
}

