def:pub toTitle(text: str) -> str {
    if (text == "") {
        return text;
    }
    title = "";
    convertNext = True;
    wasUpperCase = False;
    for i = 0 while i < len(text) with i += 1 {
        c = text[i];
        uc = c.upper();
        isUpperCase = (c == uc);
        if (c == " " or c == "_" or c == "-" or c == ".") {
            convertNext = True;
        } elif (convertNext or (isUpperCase and not wasUpperCase)) {
            if title {
                title += " ";
            }
            title += uc;
            convertNext = False;
        } else {
            title += c;
            convertNext = False;
        }
        wasUpperCase = isUpperCase;
    }
    return title;
}

