        null,
        React.createElement(HeaderUtilityMenu, {
          user: { id: 'user-1' } as any,
          isCloud: true,
          isSyncing: true,
          canShare: true,
          onOpenWatchlists: () => undefined,
          onOpenSettings: () => undefined,
          onShare: () => undefined,
