        alpha_val = str(RANDOM(40, 90) / 100);
        ox: int = RANDOM(300, 800);
        if Math.random() > 0.5 { ox = -ox; }
        oy: int = RANDOM(300, 800);
        if Math.random() > 0.5 { oy = -oy; }
        size_val = str(RANDOM(40, 90) / 100);
        new_particles: list[dict[str, int | dict[str, str]]] = [];
        for i in range(20) {
