obj DirectoryRootState {
    has fileMetadata: dict[str, Directory.FileMetadata] = {};
    has folderMetadata: dict[str, Directory.FolderMetadata] = {};
    has fileContent: dict[str, Directory.FileContent] = {};
    has fileStatus: dict[str, FileStatus] = {};
    has folderStatus: dict[str, FolderStatus] = {};
}

obj AppRootState {
    has directory: DirectoryRootState;
}

glob initialState: DirectoryRootState = DirectoryRootState(
    folderMetadata={Directory.RootNode.id: Directory.RootNode},
    folderStatus={Directory.RootNode.id: FolderStatus.Default}
);

def:pub selectFolderMetadata(folder_metadata: Directory.FolderMetadata) -> Callable[[AppRootState], Directory.FolderMetadata | None] {
    return lambda (state: AppRootState) -> Directory.FolderMetadata | None {
        return state.directory.folderMetadata.get(folder_metadata.id);
    };
}

def:pub selectFileMetadata(file_metadata: Directory.FileMetadata) -> Callable[[AppRootState], Directory.FileMetadata | None] {
    return lambda (state: AppRootState) -> Directory.FileMetadata | None {
        return state.directory.fileMetadata.get(file_metadata.id);
    };
}

def:pub selectFileContent(file_metadata: Directory.FileMetadata) -> Callable[[AppRootState], Directory.FileContent | None] {
    return lambda (state: AppRootState) -> Directory.FileContent | None {
        return state.directory.fileContent.get(file_metadata.id);
    };
}

def:pub selectFolderStatus(folder_metadata: Directory.FolderMetadata) -> Callable[[AppRootState], FolderStatus | None] {
    return lambda (state: AppRootState) -> FolderStatus | None {
        return state.directory.folderStatus.get(folder_metadata.id);
    };
}

def:pub selectAnsestors(folder_metadata: Directory.FolderMetadata) -> Callable[[AppRootState], list[Directory.FolderMetadata]] {
    return lambda (state: AppRootState) -> list[Directory.FolderMetadata] {
        current_node: Directory.FolderMetadata | None = state.directory.folderMetadata.get(folder_metadata.id);
        ansestors: list[Directory.FolderMetadata] = [];
        while (current_node is not None) and (current_node.id != Directory.RootNode.id) {
            ansestors.append(current_node);
            current_node = state.directory.folderMetadata.get(current_node.parentId);
        }
        ansestors.append(Directory.RootNode);
        ansestors.reverse();
        return ansestors;
    };
}

def:pub selectFileStatus(file_metadata: Directory.FileMetadata) -> Callable[[AppRootState], FileStatus | None] {
    return lambda (state: AppRootState) -> FileStatus | None {
        return state.directory.fileStatus.get(file_metadata.id);
    };
}

