def:pub assert(condition: object, message: str | Callable[[], str] | None = None) {
    if not condition {
        msg = message if message is not None else "Assertion failed";
        raise AssertionError.fromMessage(msg);
    }
}

def:pub assertDefined[T](value: T | None, message: str | Callable[[], str] | None = None) -> T {
    if value is None {
        default_msg = f"Expected 'value' to be defined, but received {str(value)}";
        msg = message if message is not None else default_msg;
        raise AssertionError.fromMessage(msg);
    }
    return value;
}

