import from .ops { BinaryOp, UnaryOp }

type EvalContext = dict[str, object];
type Func = Callable[..., object];

obj Node {
    def eval(ctx: EvalContext) -> object {
        raise NotImplementedError();
    }
    def toString() -> str {
        raise NotImplementedError();
    }
}

obj Literal(Node) {
    has value: object;
    def eval(ctx: EvalContext) -> object {
        return self.value;
    }
    def toString() -> str {
        if self.value is None {
            return "object(null)";
        }
        if isinstance(self.value, bool) {
            return f"boolean({str(self.value).lower()})";
        }
        if isinstance(self.value, int) or isinstance(self.value, float) {
            return f"number({self.value})";
        }
        if isinstance(self.value, str) {
            return f"string({self.value})";
        }
        return f"{type(self.value).__name__}({self.value})";
    }
}

obj NameRef(Node) {
    has name: str;
    has evalMissingNameTo: str | None = None;
    def eval(ctx: EvalContext) -> object {
        if self.name in ctx {
            return ctx[self.name];
        }
        if self.evalMissingNameTo == "error" {
            raise Exception(f'Missing name "{self.name}" in context.');
        }
        if self.evalMissingNameTo == "name" {
            return self.name;
        }
        return None;
    }
    def toString() -> str {
        return self.name;
    }
}

obj Unary(Node) {
    has op: UnaryOp;
    has arg: Node;
    def eval(ctx: EvalContext) -> object {
        return self.op(self.arg.eval(ctx));
    }
    def toString() -> str {
        op_name = self.op.__name__.lower();
        return f"{op_name}({self.arg.toString()})";
    }
}

obj Binary(Node) {
    has op: BinaryOp;
    has arg1: Node;
    has arg2: Node;
    def eval(ctx: EvalContext) -> object {
        x = self.arg1.eval(ctx);
        y = self.arg2.eval(ctx);
        return self.op(x, y);
    }
    def toString() -> str {
        op_name = self.op.__name__.lower();
        return f"{op_name}({self.arg1.toString()}, {self.arg2.toString()})";
    }
}

obj Conditional(Node) {
    has arg1: Node;
    has arg2: Node;
    has arg3: Node;
    def eval(ctx: EvalContext) -> object {
        condition = not not self.arg1.eval(ctx);
        if condition {
            return self.arg2.eval(ctx);
        }
        return self.arg3.eval(ctx);
    }
    def toString() -> str {
        return f"cond({self.arg1.toString()}, {self.arg2.toString()}, {self.arg3.toString()})";
    }
}

obj FunctionCall(Node) {
    has func: Node;
    has args: list[Node];
    def eval(ctx: EvalContext) -> object {
        fn = self.func.eval(ctx);
        values = [arg.eval(ctx) for arg in self.args];
        return (fn as Func)(*values);
    }
    def toString() -> str {
        arg_text = ", ".join([a.toString() for a in self.args]);
        return f"call({self.func.toString()}, [{arg_text}])";
    }
}

obj IndexRef(Node) {
    has arg: Node;
    has index: Node;
    def eval(ctx: EvalContext) -> object {
        base = self.arg.eval(ctx);
        idx = self.index.eval(ctx);
        return (base as list[object])[idx as int];
    }
    def toString() -> str {
        return f"idx({self.arg.toString()}, {self.index.toString()})";
    }
}

obj PropertyRef(Node) {
    has arg: Node;
    has name: str;
    def eval(ctx: EvalContext) -> object {
        base = self.arg.eval(ctx) as dict[str, object];
        return base[self.name];
    }
    def toString() -> str {
        return f"prop({self.arg.toString()}, {self.name})";
    }
}

