  "&&": AND,
  "||": OR,
  "==": EQ,
  "!=": NEQ,
  ">=": GEQ,
  "<=": LEQ,
  "<": LT,
  ">": GT,
  "+": ADD,
  "-": SUB,
  "*": MUL,
  "/": DIV,
