import from "@/core/types" { Extension, ExtensionStatus }
import from "@/core/extension/get" { getExtension }
import from "@/core/store" { setStoreRecord }
import from "@/util/log" { Logger, LogLevel }

glob LOG = Logger.getLogger("extendit/core");

def:pub setExtensionStatus(
    extensionId: str,
    status: ExtensionStatus,
    *args: object
) -> Extension {
    prevExtension = getExtension(extensionId, True);
    nextExtension: Extension = {**prevExtension, "status": status} as Extension;
    if status == "active" {
        exports = args[0];
        nextExtension = {**nextExtension, "exports": exports} as Extension;
    } elif status == "rejected" {
        reasons: list[Exception] = [];
        for r in args {
            if isinstance(r, Exception) {
                reasons.append(r as Exception);
            } elif isinstance(r, str) {
                reasons.append(Exception(r));
            } else {
                reasons.append(Exception(str(r)));
            }
        }
        prevReasons = prevExtension.reasons if prevExtension.reasons is not None else [];
        nextExtension = {**nextExtension, "reasons": reasons + prevReasons} as Extension;
    }
    setStoreRecord("extensions", extensionId, nextExtension);
    level = LogLevel.ERROR if nextExtension.status == "rejected" else LogLevel.DEBUG;
    LOG.log(level, "setExtensionStatus", nextExtension);
    return nextExtension;
}

