  nodeCounter?: number;
}

export interface TreeAction {
  type: TreeActionTypes;
  payload?: TreeActionPayload;
}

/**
 * Custom type to override the 'react-d3-tree' tree node.
 */
export type UnionedTreeData = TreeData | ReactD3TreeItem;

