import from "../../components/ui" { Card, Loading }
import from "../../services/restaurantService" { getRestaurantStats }
import from "../../utils/helpers" { formatCurrency }

def:pub RestaurantHome() -> JsxElement {
    has stats: dict[str, int | float] | None = None;
    has loading: bool = True;

    async def load_stats() -> None {
        userRaw = localStorage.getItem("user") or "{}";
        user = JSON.parse(userRaw) as dict[str, str];
        if not user.get("restaurant_id") {
            loading = False;
            return;
        }
        data = await getRestaurantStats(user["restaurant_id"]);
        stats = data as dict[str, int | float];
        loading = False;
    }

    async can with entry {
        await load_stats();
    }

    if loading {
        return <Loading text="Loading dashboard..." />;
    }

    pendingOrders = stats["pendingOrders"] as int if stats else 0;
    todayOrders = stats["todayOrders"] as int if stats else 0;
    todayRevenue = stats["todayRevenue"] as float if stats else 0;
    totalMenuItems = stats["totalMenuItems"] as int if stats else 0;

    statCards = [
        {"title": "Pending Orders", "value": str(pendingOrders), "icon": "⏰", "color": "text-warning", "bgColor": "bg-warning/10"},
        {"title": "Today's Orders", "value": str(todayOrders), "icon": "🛍️", "color": "text-accent", "bgColor": "bg-accent/10"},
        {"title": "Today's Revenue", "value": formatCurrency(todayRevenue), "icon": "💲", "color": "text-success", "bgColor": "bg-success/10"},
        {"title": "Menu Items", "value": str(totalMenuItems), "icon": "🍴", "color": "text-accent-secondary", "bgColor": "bg-accent-secondary/10"},
    ];

    <div className="space-y-6">
        <div>
            <h2 className="text-2xl font-bold text-text mb-2">Dashboard</h2>
            <p className="text-text-secondary">
                Welcome back! Here's your restaurant overview
            </p>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
