import from "./input-group.styles" { inputGroupStyles, inputAddonStyles, INPUT_GROUP_SIZES }
import from "react" { Children, isValidElement, cloneElement, ReactElement }

type Size = Literal["xs", "sm", "md", "lg", "xl", "2xl", "3xl"];
type Placement = Literal["start", "end"];
type PointerEvents = Literal["auto", "none"];

def resolvePointerEventsClass(value: PointerEvents | None) -> str {
    if value == "auto" {
        return inputGroupStyles["elementPointerAuto"] as str;
    }
    if value == "none" {
        return inputGroupStyles["elementPointerNone"] as str;
    }
    return inputGroupStyles["elementPointerSmart"] as str;
}

def:pub InputAddon(
    children: object | None = None,
    size: Size = "md",
    placement: Placement = "start",
    className: str | None = None,
    props: dict[str, object] = {},
    ref: Ref[HTMLDivElement] = Ref(),
) -> JsxElement {
    sizeStyles = INPUT_GROUP_SIZES[size] as dict[str, object];
    addonClass = sizeStyles["addon"] as str;
    placementClass = inputGroupStyles["start"] as str if placement == "start" else inputAddonStyles["end"] as str;
    <div
        ref={ref}
        data-slot="addon"
        className={cn(inputAddonStyles["base"] as str, placementClass, addonClass, className)}
        {**props}
    >
        {children}
    </div>
}

def:pub InputGroup(
    children: object | None = None,
    size: Size = "md",
    startElement: object | None = None,
    endElement: object | None = None,
    startElementPointerEvents: PointerEvents | None = None,
    endElementPointerEvents: PointerEvents | None = None,
    className: str | None = None,
    props: dict[str, object] = {},
    ref: Ref[HTMLDivElement] = Ref(),
) -> JsxElement {
    sizeStyles = INPUT_GROUP_SIZES[size] as dict[str, object];
    elementPadding = sizeStyles["elementPadding"] as dict[str, str];
    elementClass = sizeStyles["element"] as str;
    enhancedChildren = children;
    if children {
        enhancedChildren = Children.map(children, lambda (child: object) -> object {
            if isValidElement(child) {
                elt = child as ReactElement;
                childProps = elt.props as dict[str, object];
                additionalClasses = cn(
                    elementPadding["start"] if startElement else "",
                    elementPadding["end"] if endElement else ""
                );
                childClass = childProps.get("className") as str | None;
                childSize = childProps.get("size");
                return cloneElement(elt, {
                    "className": cn(childClass, additionalClasses),
                    "size": childSize if childSize else size,
                });
            }
            return child;
        });
    }
    <div ref={ref} data-slot="input-group" className={cn(inputGroupStyles["container"] as str, className)} {**props}>
        <div className={inputGroupStyles["wrapper"] as str}>
            {if startElement {
                <div
                    data-slot="start-element"
                    className={cn(
                        inputGroupStyles["element"] as str,
                        inputGroupStyles["elementStart"] as str,
                        elementClass,
                        resolvePointerEventsClass(startElementPointerEvents)
                    )}
                >
                    {startElement}
                </div>
            }}
            {enhancedChildren}
            {if endElement {
                <div
                    data-slot="end-element"
                    className={cn(
                        inputGroupStyles["element"] as str,
                        inputGroupStyles["elementEnd"] as str,
                        elementClass,
                        resolvePointerEventsClass(endElementPointerEvents)
                    )}
                >
                    {endElement}
                </div>
            }}
        </div>
    </div>
}

