import from "@ninna-ui/utils" { cn }

glob LOADING_VARIANT_CLASSES: dict[str, str] = {
    "spin": "animate-spin rounded-full border-2 border-current border-t-transparent",
    "ping": "animate-ping rounded-full",
    "pulse": "animate-pulse rounded-full",
    "dots": "inline-flex items-center gap-2",
};

glob LOADING_COLOR_CLASSES: dict[str, str] = {
    "primary": "text-primary",
    "secondary": "text-secondary",
    "accent": "text-accent",
    "neutral": "text-neutral",
    "success": "text-success",
    "danger": "text-danger",
    "warning": "text-warning",
    "info": "text-info",
};

glob LOADING_SIZE_CLASSES: dict[str, str] = {
    "xs": "h-3 w-3",
    "sm": "h-4 w-4",
    "md": "h-5 w-5",
    "lg": "h-6 w-6",
    "xl": "h-8 w-8",
    "2xl": "h-10 w-10",
    "3xl": "h-12 w-12",
};

def loadingVariants(
    variant: str | None = None,
    color: str | None = None,
    size: str | None = None,
) -> str {
    v = variant if variant is not None else "spin";
    c = color if color is not None else "primary";
    s = size if size is not None else "md";
    classes = cn("", LOADING_VARIANT_CLASSES.get(v, ""), LOADING_COLOR_CLASSES.get(c, ""), LOADING_SIZE_CLASSES.get(s, ""));
    if v == "dots" {
        return cn(classes, "h-auto w-auto");
    }
    return classes;
}

obj:pub LoadingVariantsProps {
    has variant: str | None = None;
    has color: str | None = None;
    has size: str | None = None;
}

