import from "@ninna-ui/utils" { cn }
import from "./status.styles" { statusIndicatorVariants, statusLabelVariants, STATUS_ROOT_CLASS }

def:pub Status(
    value: str | None = None,
    size: str | None = None,
    children: object | None = None,
    className: str | None = None,
    ref: Ref[object] = Ref(),
    props: dict[str, object] | None = None,
) -> JsxElement {
