    width: int,
    height: int,
    stroke: str = "#f1f117",
    strokeWidth: int = 4,
    ref: Ref = Ref(),
) -> JsxElement {
    <svg
        className="svg-options"
        width={width}
        height={height}
        xmlns="http://www.w3.org/2000/svg"
        ref={ref}
    >
        {if type == "rect" {
            <rect
                width={width}
                height={height}
                stroke={stroke}
                fill="transparent"
                strokeWidth={strokeWidth}
            />
        }}
        {if type == "circle" {
            <ellipse
                cx={width / 2}
                cy={height / 2}
                rx={width / 2}
                ry={height / 2}
                stroke={stroke}
                fill="transparent"
                strokeWidth={strokeWidth}
            />
        }}
    </svg>
}

