def:pub useEscapeKey(options: UseEscapeKeyOptions) {
    enabled = options.enabled;
    onEscape = options.onEscape;
    priority = options.priority;
    useEffect(lambda {
        if not enabled {
            return lambda { };
        }
        def handleEscape(e: KeyboardEvent) {
