def parse_article(data: dict[str, object]) -> WikiArticle {
    thumb = None;
    if "thumbnail" in data {
        thumb_raw = data["thumbnail"] as dict[str, str];
        thumb = WikiThumbnail(source=thumb_raw["source"]);
    }
    content_urls = data["content_urls"] as dict[str, dict[str, str]];
    return WikiArticle(
        title=data["title"] as str,
        extract=data["extract"] as str,
        url=content_urls["desktop"]["page"],
        thumbnail=thumb,
    );
}

