import re;

obj BlockReference {
    has noteTitle: str;
    has blockId: str | None = None;
}

obj BlockContentResult {
    has content: str;
    has context: str;
}

def:pub slugify(text: str) -> str {
    step1 = re.sub(r'[^\w\s-]', '', text.lower().strip());
    step2 = re.sub(r'\s+', '-', step1);
    step3 = re.sub(r'-+', '-', step2);
    return re.sub(r'^-+|-+$', '', step3);
}

def:pub parseBlockReference(linkTitle: str) -> BlockReference {
    hashIndex = linkTitle.find("#");
    if hashIndex == -1 {
        return BlockReference(noteTitle=linkTitle.strip(), blockId=None);
    }
    return BlockReference(
        noteTitle=linkTitle[0:hashIndex].strip(),
        blockId=linkTitle[(hashIndex + 1):].strip()
    );
}

def:pub extractBlockId(text: str) -> str | None {
    regexMatch = re.search(r'\^([\w-]+)\s*$', text);
    if regexMatch {
        return regexMatch.group(1);
    }
    return None;
}

def:pub removeBlockIdMarker(text: str) -> str {
    return re.sub(r'\s*\^[\w-]+\s*$', '', text).strip();
}

def getContext(lines: list[str], targetIndex: int) -> str {
    contextLines: list[str] = [];
    if targetIndex > 0 {
        contextLines.append(lines[targetIndex - 1]);
    }
    contextLines.append(lines[targetIndex]);
    if targetIndex < (len(lines) - 1) {
        contextLines.append(lines[targetIndex + 1]);
    }
    return "\n".join(contextLines);
}

def:pub findBlockInContent(content: str, blockId: str) -> BlockContentResult | None {
    if not content or not blockId {
        return None;
    }
    lines = content.split("\n");
    blockIdLower = blockId.lower();
    for i = 0 while i < len(lines) with i += 1 {
        line = lines[i];
        manualId = extractBlockId(line);
        if manualId and manualId.lower() == blockIdLower {
            blockContent = removeBlockIdMarker(line);
            context = getContext(lines, i);
            return BlockContentResult(content=blockContent, context=context);
        }
    }
    for i = 0 while i < len(lines) with i += 1 {
        line = lines[i];
        headingMatch = re.match(r'^(#+)\s+(.+)$', line);
        if headingMatch {
            headingText = headingMatch.group(2);
            headingSlug = slugify(headingText);
            if headingSlug == blockIdLower {
                context = getContext(lines, i);
                return BlockContentResult(content=headingText, context=context);
            }
        }
    }
    return None;
}

def:pub extractBlockReferences(content: str) -> list[BlockReference] {
    if not content {
        return [];
    }
    blockRefs: list[BlockReference] = [];
    wikiLinkPattern = re.compile(r'\[\[([^\]]+)\]\]');
    for regexMatch in wikiLinkPattern.finditer(content) {
        linkTitle = regexMatch.group(1).strip();
        blockRef = parseBlockReference(linkTitle);
        if blockRef.blockId {
            blockRefs.append(blockRef);
        }
    }
    return blockRefs;
}

def:pub createBlockReference(noteTitle: str, blockId: str) -> str {
    return f"[[{noteTitle}#{blockId}]]";
}

def:pub hasBlockReference(linkTitle: str) -> bool {
    return "#" in linkTitle;
}

