        return FuzzyMatch(score=score, matchedIndices=indices);
    }
    queryIdx = 0;
    matchedIndices: list[int] = [];
    consecutiveMatches = 0;
    maxConsecutive = 0;
    lastMatchIdx = -1;
    for targetIdx = 0 while targetIdx < len(targetLower) and queryIdx < len(queryLower) with targetIdx += 1 {
        if targetLower[targetIdx] == queryLower[queryIdx] {
            matchedIndices.append(targetIdx);
