        return None;
    }
    matchRatio = float(len(queryLower)) / float(len(target));
    consecutiveBonus = float(maxConsecutive) / float(len(queryLower));
    spread = (matchedIndices[len(matchedIndices) - 1] - matchedIndices[0]) + 1;
    compactness = float(len(queryLower)) / float(spread);
    wordStartBonus = 0.0;
    for idx in matchedIndices {
        if idx == 0 or targetLower[idx - 1] == " " or targetLower[idx - 1] == "-" or targetLower[idx - 1] == "_" {
            wordStartBonus += 0.1;
        }
    }
    wordStartBonus = min(wordStartBonus, 0.3);
    score = min(
        (((((matchRatio * 0.3) + (consecutiveBonus * 0.3)) + (compactness * 0.2)) + wordStartBonus) + 0.1) * 0.85,
        0.85
    );
    return FuzzyMatch(score=score, matchedIndices=matchedIndices);
}

def:pub fuzzySearch(
    items: list[dict[str, object]],
    query: str,
    fields: list[FuzzySearchField],
    maxResults: int = 50
) -> list[FuzzySearchResult] {
    if not query.strip() {
        return [];
    }
    results: list[FuzzySearchResult] = [];
    for item in items {
        bestScore = 0.0;
        matches: dict[str, list[int]] = {};
        for field in fields {
            value = item.get(field.key);
            if isinstance(value, str) {
                fuzzyResult = fuzzyMatch(query, value);
                if fuzzyResult is not None {
                    weightedScore = fuzzyResult.score * field.weight;
                    if weightedScore > bestScore {
                        bestScore = weightedScore;
                    }
                    matches[field.key] = fuzzyResult.matchedIndices;
                }
            }
        }
        for field in fields {
            value = item.get(field.key);
            if isinstance(value, list) {
                for arrayItem in value {
                    if isinstance(arrayItem, str) {
                        fuzzyResult = fuzzyMatch(query, arrayItem);
                        if fuzzyResult is not None {
                            weightedScore = fuzzyResult.score * field.weight;
                            if weightedScore > bestScore {
                                bestScore = weightedScore;
                            }
                            matches[field.key] = fuzzyResult.matchedIndices;
                        }
                    }
                }
            }
        }
        if bestScore > 0.0 {
            results.append(FuzzySearchResult(item=item, score=bestScore, matches=matches));
        }
    }
    results.sort(key=lambda (r: FuzzySearchResult) -> float { return r.score; }, reverse=True);
    return results[0:maxResults];
}

