import re;

obj NoteTemplateInput {
    has id: str | None = None;
    has name: str | None = None;
    has description: str | None = None;
}

obj ValidationResult {
    has valid: bool;
    has errors: list[str];
}

obj ValidateAndSanitizeResult {
    has valid: bool;
    has errors: list[str];
    has sanitized: NoteTemplateInput | None = None;
}

def:pub validateNoteTemplate(
    template: NoteTemplateInput,
    existingTemplates: list[NoteTemplateInput] | None = None
) -> ValidationResult {
    errors: list[str] = [];
    templates = existingTemplates if existingTemplates is not None else [];
    if template.name is None or len(template.name.strip()) == 0 {
        errors.append("Name is required");
    } else {
        if len(template.name) < 1 or len(template.name) > 100 {
            errors.append("Name must be between 1 and 100 characters");
        }
        nameLower = template.name.lower();
        isDuplicate = False;
        for t in templates {
            if t.id != template.id and t.name is not None and t.name.lower() == nameLower {
                isDuplicate = True;
                break;
            }
        }
        if isDuplicate {
            errors.append(f"Template with name \"{template.name}\" already exists");
        }
    }
    if template.description is None or len(template.description.strip()) == 0 {
        errors.append("Description is required");
    } else {
        if len(template.description) < 1 or len(template.description) > 50000 {
            errors.append("Description must be between 1 and 50000 characters");
        }
    }
    return ValidationResult(valid=len(errors) == 0, errors=errors);
}

def:pub sanitizeTemplateContent(content: str) -> str {
    if not content {
        return "";
    }
    sanitized = content;
    sanitized = re.sub(r'(?i)<script\b[^<]*(?:(?!</script>)<[^<]*)*</script>', '', sanitized);
    sanitized = re.sub(r'(?i)\son\w+\s*=\s*["\'][^"\']*["\']', '', sanitized);
    sanitized = re.sub(r'(?i)javascript:', '', sanitized);
    sanitized = re.sub(
        r'(?i)data:(?!image/(png|jpg|jpeg|gif|webp|svg\+xml);base64,)[^\s"\']+',
        '',
        sanitized
    );
    sanitized = re.sub(r'(?i)<style\b[^<]*(?:(?!</style>)<[^<]*)*</style>', '', sanitized);
    sanitized = re.sub(r'(?i)<(iframe|object|embed)\b[^>]*>', '', sanitized);
    sanitized = sanitized.strip();
    return sanitized;
}

def:pub sanitizeTemplateName(name: str) -> str {
    if not name {
        return "";
    }
    sanitized = name;
    sanitized = re.sub(r'[\x00-\x1F\x7F]', '', sanitized);
    sanitized = re.sub(r'\s+', ' ', sanitized);
    sanitized = sanitized.strip();
    return sanitized;
}

def:pub validateAndSanitizeTemplate(
    template: NoteTemplateInput,
    existingTemplates: list[NoteTemplateInput] | None = None
) -> ValidateAndSanitizeResult {
    sanitized = NoteTemplateInput(
        id=template.id,
        name=sanitizeTemplateName(template.name if template.name else ""),
        description=sanitizeTemplateContent(template.description if template.description else "")
    );
    validation = validateNoteTemplate(sanitized, existingTemplates);
    if validation.valid {
        return ValidateAndSanitizeResult(valid=True, errors=[], sanitized=sanitized);
    }
    return ValidateAndSanitizeResult(valid=validation.valid, errors=validation.errors, sanitized=None);
}

