import from datetime { datetime }

obj Note {
    has tags: list[str] = [];
    has isArchived: bool = False;
    has updatedAt: datetime = datetime.now();
}

obj TagSuggestion {
    has tag: str;
    has reason: str;
    has weight: float;
}

def extractKeywords(content: str, allTags: list[str]) -> list[str] {
    normalized = content.lower();
    keywords: list[str] = [];
    for tag in allTags {
        tagParts = tag.lower().split("/");
        for part in tagParts {
            if len(part) > 2 and part in normalized and tag not in keywords {
                keywords.append(tag);
            }
        }
    }
    return keywords;
}

def getMostFrequentTags(notes: list[Note], limit: int) -> list[str] {
    tagCounts: dict[str, int] = {};
    for note in notes {
        if not note.isArchived {
            for tag in note.tags {
                tagCounts[tag] = tagCounts.get(tag, 0) + 1;
            }
        }
    }
    entries = sorted(tagCounts.items(), key=lambda (item: tuple[str, int]) -> int { return item[1]; }, reverse=True);
    return [tag for (tag, _count) in entries[0:limit]];
}

def getCoOccurringTags(existingTags: list[str], notes: list[Note]) -> dict[str, int] {
    coOccurrence: dict[str, int] = {};
    for note in notes {
        if note.isArchived {
            continue;
        }
        hasExistingTag = False;
        for tag in existingTags {
            if tag in note.tags {
                hasExistingTag = True;
                break;
            }
        }
        if not hasExistingTag {
            continue;
        }
        for tag in note.tags {
            if tag not in existingTags {
                coOccurrence[tag] = coOccurrence.get(tag, 0) + 1;
            }
        }
    }
    return coOccurrence;
}

def getHierarchicalSuggestions(existingTags: list[str], allTags: list[str]) -> list[str] {
    suggestions: list[str] = [];
    for parentTag in existingTags {
        prefix = parentTag + "/";
        for tag in allTags {
            if tag.startswith(prefix) and tag not in existingTags and tag not in suggestions {
                suggestions.append(tag);
            }
        }
    }
    return suggestions;
}

def getRecentTags(notes: list[Note], limit: int, excludeTags: list[str]) -> list[str] {
    recentTags: list[str] = [];
    tagSet: set[str] = set(excludeTags);
    sortedNotes = sorted(
        [note for note in notes if not note.isArchived],
        key=lambda (n: Note) -> float { return n.updatedAt.timestamp(); },
        reverse=True,
    );
    for note in sortedNotes {
        for tag in note.tags {
            if tag not in tagSet {
                tagSet.add(tag);
                recentTags.append(tag);
                if len(recentTags) >= limit {
                    return recentTags;
                }
            }
        }
    }
    return recentTags;
}

def:pub generateTagSuggestions(
    content: str,
    existingTags: list[str],
    allNotes: list[Note],
    maxSuggestions: int = 5,
) -> list[TagSuggestion] {
    suggestions: dict[str, TagSuggestion] = {};
    allTagsSet: set[str] = set();
    for note in allNotes {
        for tag in note.tags {
            allTagsSet.add(tag);
        }
    }
    allTags = list(allTagsSet);
    for tag in extractKeywords(content, allTags) {
        if tag not in existingTags {
            suggestions[tag] = TagSuggestion(tag=tag, reason="content", weight=1.0);
        }
    }
    for tag in getMostFrequentTags(allNotes, maxSuggestions * 2) {
        if tag not in existingTags and tag not in suggestions {
            suggestions[tag] = TagSuggestion(tag=tag, reason="frequency", weight=0.7);
        }
    }
    coOccurring = getCoOccurringTags(existingTags, allNotes);
    for (tag, count) in coOccurring.items() {
        if tag not in existingTags and tag not in suggestions {
            suggestions[tag] = TagSuggestion(tag=tag, reason="co-occurrence", weight=0.5 + (count * 0.1));
        }
    }
    for tag in getHierarchicalSuggestions(existingTags, allTags) {
        if tag not in suggestions {
            suggestions[tag] = TagSuggestion(tag=tag, reason="hierarchical", weight=0.6);
        }
    }
    for tag in getRecentTags(allNotes, maxSuggestions * 2, existingTags) {
        if tag not in suggestions {
            suggestions[tag] = TagSuggestion(tag=tag, reason="recent", weight=0.4);
        }
    }
    ranked = sorted(
        suggestions.values(),
        key=lambda (s: TagSuggestion) -> float { return s.weight; },
        reverse=True,
    );
    return ranked[0:maxSuggestions];
}

