glob TOAST_REMOVE_DELAY: int = 1000000;
glob actionTypes: dict[str, str] = {"ADD_TOAST": "ADD_TOAST", "UPDATE_TOAST": "UPDATE_TOAST", "DISMISS_TOAST": "DISMISS_TOAST", "REMOVE_TOAST": "REMOVE_TOAST"};
glob listeners: list[Callable[[], None]] = [];

