def:pub useResizeContext[T](reducer: Callable[[Size | None], T] | None = None) -> Size | None | T {
    ctx = useContext(Context);
    size: Size | None = ctx.size;
    if reducer {
        result: T = reducer(size);
        return useMemo(lambda { result; }, [result]);
    }
    return useMemo(lambda { size; }, [size]);
}

