import from builtins { setattr, getattr }

def set_resolve(img: HTMLImageElement, resolve: Callable) {
    setattr(img, "onload", lambda {
        call_fn = getattr(resolve, "call");
        call_fn(None, img);
    });
}

async def loadImageHandler(src: str) -> HTMLImageElement {
    create_el = getattr(document, "createElement");
    img = create_el("img") as HTMLImageElement;
    setattr(img, "crossOrigin", "Anonymous");
    promise_ctor = getattr(globalThis, "Promise") as type[object];
    loaded = new(promise_ctor, lambda (resolve: Callable, _reject: Callable) {
        set_resolve(img, resolve);
    }) as Awaitable[HTMLImageElement];
    setattr(img, "src", src);
    return await loaded;
}

