import from "react" { isValidElement }

obj SlideObjectOptions {
    has isBaseStyle: bool = False;
}

obj SlideObject {
    has render: Callable[[], JsxElement];
    has options: SlideObjectOptions = SlideObjectOptions();
}

type Slide = Callable[[], JsxElement] | SlideObject;

def isJSXElementFunction(fn: object) -> bool {
    if not callable(fn) {
        return False;
    }
    try {
        result = (fn as Callable[[], JsxElement])();
        return isValidElement(result);
    } except Exception {
        return False;
    }
}

def renderSlideComponent(slide: Slide) -> Callable[[], JsxElement] {
    if isJSXElementFunction(slide) {
        return slide as Callable[[], JsxElement];
    }
    if isinstance(slide, SlideObject) {
        return slide.render;
    }
    return lambda { <></>; };
}

def genSlideObject(
    component: Callable[[], JsxElement],
    options: SlideObjectOptions | None = None
) -> SlideObject {
    merged = SlideObjectOptions(isBaseStyle=False);
    if options is not None {
        merged = SlideObjectOptions(isBaseStyle=options.isBaseStyle);
    }
    return SlideObject(render=component, options=merged);
}

