import re;
import random;
import time;

def to_base36(n: int) -> str {
    alphabet = "0123456789abcdefghijklmnopqrstuvwxyz";
    if n == 0 {
        return "0";
    }
    result = "";
    num = n;
    while num > 0 {
        result = alphabet[num % 36] + result;
        num = num // 36;
    }
    return result;
}

def:pub generateSlug(name1: str, name2: str) -> str {
    combined = f"{name1}-and-{name2}";
    combined = combined.lower();
    combined = re.sub(r"[^a-z0-9]+", "-", combined);
    combined = re.sub(r"^-+|-+$", "", combined);
    return combined;
}

def:pub generateUniqueSlug(baseName: str) -> str {
    timestamp = to_base36(int(time.time() * 1000));
    random_str = to_base36(random.getrandbits(30))[2:7];
    return f"{baseName}-{timestamp}{random_str}";
}

js:
export function generateSlug(name1: string, name2: string): string {
  const combined = `${name1}-and-${name2}`;
  return combined
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export function generateUniqueSlug(baseName: string): string {
  const timestamp = Date.now().toString(36);
  const random = Math.random().toString(36).substring(2, 7);
  return `${baseName}-${timestamp}${random}`;
}

