def:pub Hint(
    text: str,
    position: str | None = None,
    padding: float | None = None,
    children: str | JsxElement | None = None,
) -> JsxElement {
    position = position or "top-left";
    padding = 0 + (padding or 0);
    hintStyle: dict[str, object] = {"position": "absolute"};
    if position == "top-left" {
        hintStyle = {**hintStyle, "top": padding, "left": padding};
    } elif position == "top-right" {
        hintStyle = {**hintStyle, "top": padding, "right": padding};
    } elif position == "bottom-left" {
        hintStyle = {**hintStyle, "bottom": padding, "left": padding};
    } elif position == "bottom-right" {
        hintStyle = {**hintStyle, "bottom": padding, "right": padding};
    }
    <div style={{"position": "relative"}} className="hint">
        {children}
        <div style={hintStyle}>
            <div className="relative group">
                <div className="w-5 h-5 flex justify-center items-center cursor-help opacity-40 hover:opacity-100 transition-opacity">
                    <FontAwesomeIcon icon={faInfoCircle} />
                </div>
                <span className="absolute md:w-32 left-1/2 transform -translate-x-1/2 top-7 scale-0 rounded bg-gray-800 p-2 text-xs text-white group-hover:scale-100 transition-transform ease-in-out z-50">
                    {text}
                </span>
            </div>
        </div>
    </div>
}

