def:pub Step(
    style: dict[str, object] | None = None,
    icon: object | None = None,
    title: object | None = None,
    description: str | None = None,
    _index: int = 0,
    _current: int = 0,
    _status: str = "wait",
) -> JsxElement {
    iconVal = icon if icon is not None else defaultIcon();
    styleVal = style if style is not None else {};
    currentStatus = _status;
    if _status == "error" and (_index + 1) == _current {
        styleVal = {**styleVal, "--line-to-next-color": "var(--fam-color-danger)"};
    }
    if _index < _current {
        currentStatus = "finish";
    } elif _index > _current {
        currentStatus = "wait";
    }
    wrapCls = classnames(prefixCls, f"{prefixCls}-status-{currentStatus}");
    <div className={wrapCls}>
        <div className={f"{prefixCls}-indicator"} style={styleVal}>
            <div className={f"{prefixCls}-icon-container"}>{iconVal if icon else _index}</div>
        </div>
        <div className={f"{prefixCls}-content"}>
            <div className={f"{prefixCls}-title"}>{title}</div>
            {if description {
                <div className={f"{prefixCls}-description"}>{description}</div>
            }}
        </div>
    </div>
}

