def:pub navbar(
    title: object | None = None,
    onLeftClick: Callable[[MouseEvent], None] | None = None,
    leftContent: object | None = None,
    rightContent: object | None = None,
    icon: object | None = None,
    children: object | None = None,
    mode: str = "dark",
    fixed: bool = False,
    placeholder: bool = False,
    zIndex: int = 9,
    className: str | None = None,
    style: dict[str, object] | None = None,
) -> JsxElement {
    wrapCls = classnames(prefixCls, className, f"{prefixCls}-{mode}", {f"{prefixCls}-fixed": fixed});
