    def handle_left_click(e: MouseEvent) {
        if onLeftClick {
            onLeftClick(e);
        }
    }
    return <>
        <div className={wrapCls} style={barStyle}>
            <div className={f"{prefixCls}-left"} role="button" onClick={handle_left_click}>
