            <div className={f"{prefixCls}-title"}>{children if children else title}</div>
            <div className={f"{prefixCls}-right"}>{rightContent}</div>
        </div>
        {if placeholder and fixed {
            <div className={f"{prefixCls}-placeholder"} />
