}

export function toProfileCreateResult(raw: Record<string, unknown>): ProfileCreateResult {
  return {
    ok: raw.ok === true,
    name: typeof raw.name === 'string' ? raw.name : '',
    ...(typeof raw.path === 'string' ? { path: raw.path } : {}),
    ...(raw.model_set === true ? { model_set: true } : {}),
  };
}

