import { useEffect, useState } from 'react';
import type { RestClient } from '@hermes-pwa/core';
import { Icon, type IconName } from '../components/Icon';

interface SkillsProps {
  rest: RestClient;
}

type SkillTag = 'built-in' | 'plugin' | 'custom' | 'core' | 'guarded' | 'ops';

interface Skill {
  id: string;
  name: string;
  description: string | undefined;
  tag: SkillTag;
  enabled: boolean;
  icon: string | undefined;
}

const ICON_NAMES = new Set<string>([
  'menu',
  'home',
  'chat',
  'check',
  'sessions',
  'kanban',
  'cron',
  'agents',
  'robot',
  'system',
  'settings',
  'skills',
  'messaging',
  'search',
  'plus',
  'mic',
  'wave',
  'arrowUp',
  'bolt',
  'chevR',
  'chevD',
  'close',
  'branch',
  'play',
  'refresh',
  'shield',
  'terminal',
  'alert',
  'sparkle',
  'archive',
]);

function isIconName(value: string): value is IconName {
  return ICON_NAMES.has(value);
}

function parseSkill(raw: Record<string, unknown>): Skill {
  const str = (v: unknown) => (typeof v === 'string' && v ? v : undefined);
  const tagRaw = typeof raw.tag === 'string' ? raw.tag : typeof raw.type === 'string' ? raw.type : 'built-in';
  const tag: SkillTag =
    tagRaw === 'core' || tagRaw === 'guarded' || tagRaw === 'ops' || tagRaw === 'plugin' || tagRaw === 'custom'
      ? (tagRaw as SkillTag)
      : 'built-in';
  return {
    id: String(raw.id ?? raw.name ?? ''),
    name: String(raw.name ?? raw.id ?? 'Skill'),
    description: str(raw.description),
    tag,
    enabled: raw.enabled !== false,
    icon: str(raw.icon),
  };
}

const TAG_LABEL: Record<SkillTag, string> = {
  'built-in': 'CORE',
  plugin: 'PLUGIN',
  custom: 'CUSTOM',
  core: 'CORE',
  guarded: 'GUARDED',
  ops: 'OPS',
};

export function Skills({ rest }: SkillsProps) {
  const [skills, setSkills] = useState<Skill[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | undefined>(undefined);

  useEffect(() => {
    void rest
      .skillsList()
      .then((raw) => setSkills((raw as unknown as Record<string, unknown>[]).map(parseSkill)))
      .catch((err) => setError(err instanceof Error ? err.message : 'Failed to load'))
      .finally(() => setLoading(false));
  }, [rest]);

  return (
    <div className="hm-skills">
      <p className="hm-skills__subtitle">Skills &amp; tools available to the active profile.</p>

      {error && <div className="hm-warning-banner hm-warning-banner--error">{error}</div>}
      {loading && <p className="hm-muted hm-loading">Loading skills…</p>}

      {skills.length === 0 && !loading ? (
        <div className="hm-empty-state">
          <p>No skills available</p>
        </div>
      ) : (
        <div className="hm-skills__list">
          {skills.map((skill) => (
            <div key={skill.id} className="hm-skill-row" data-testid="skill-row" data-tag={skill.tag}>
              <span className="hm-skill-row__icon" aria-hidden="true">
                {skill.icon && isIconName(skill.icon) ? (
                  <Icon name={skill.icon} size={18} />
                ) : (
                  skill.icon ?? '⚡'
                )}
              </span>
              <span className="hm-skill-row__body">
                <span className="hm-skill-row__name">{skill.name}</span>
                <span className="hm-skill-row__desc hm-muted">{skill.description}</span>
              </span>
              <span className="hm-skill-row__tag">{TAG_LABEL[skill.tag]}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import React from 'react';
import { axe } from 'jest-axe';

import { Accordion } from '~components';
import { userEvent, render, screen } from '~lib/test-utils';

jest.mock('../Icon/library/chevron-bottom.svg', () => 'div');

const title = 'accordion title';
const content = 'accordion content';

test('[Accordion] should not fail accessibility testing', async () => {
  const { container } = render(<Accordion title="title">content</Accordion>);

  expect(await axe(container)).toHaveNoViolations();
});

test('renders string content', () => {
  render(
    <Accordion title={title} data-testid="accordion">
      {content}
    </Accordion>,
  );

  const element = screen.getByTestId('accordion');
  const contentBox = screen.getByText(content).parentElement;
  const contentBoxParent = contentBox.parentElement;

  expect(window.getComputedStyle(contentBox).opacity).toBe('0');
  expect(window.getComputedStyle(contentBoxParent).maxHeight).toBe('0');

  userEvent.click(element);
  expect(window.getComputedStyle(contentBox).opacity).toBe('1');
  expect(window.getComputedStyle(contentBoxParent).maxHeight).toBe('500px');

  userEvent.click(element);
  expect(window.getComputedStyle(contentBox).opacity).toBe('0');
  expect(window.getComputedStyle(contentBoxParent).maxHeight).toBe('0');
});

test('renders custom content', () => {
  render(
    <Accordion title={title} data-testid="accordion">
      <div data-testid="accordion-custom-content">{content}</div>
    </Accordion>,
  );

  const element = screen.getByTestId('accordion');
  const contentBox = screen.getByTestId('accordion-custom-content')
    .parentElement.parentElement;

  expect(window.getComputedStyle(contentBox).maxHeight).toBe('0');

  userEvent.click(element);
  expect(window.getComputedStyle(contentBox).maxHeight).toBe('500px');

  userEvent.click(element);
  expect(window.getComputedStyle(contentBox).maxHeight).toBe('0');
});

