def:pub useLocalStorage[T](key: str, defaultValue: T) -> list[object] {
    def init_value() -> T {
        try {
            value = localStorage.getItem(key);
            if value {
                return json.loads(value) as T;
            }
            localStorage.setItem(key, json.dumps(defaultValue));
            return defaultValue;
        } except Exception {
            localStorage.setItem(key, json.dumps(defaultValue));
            return defaultValue;
        }
    }

    state = useState(init_value);
    localStorageValue = state[0] as T;
    setLocalStorageValue = state[1] as Callable[[T], None];

    def setLocalStorageStateValue(newValue: T) {
        localStorage.setItem(key, json.dumps(newValue));
        setLocalStorageValue(newValue);
    }

    return [localStorageValue, setLocalStorageStateValue];
}

