            label='Author'
            id='author'
            placeholder='Lewis Carroll'
            value={props.author}
            setter={props.setAuthor}
            maxLength={50}
            required={props.generationFormat === 'commands'}
          />
        </div>
        <div className='w-full sm:w-1/2 px-2'>
          <TextInput
            label='Title'
            id='title'
            placeholder='Alice in Wonderland'
            value={props.title}
