import React from 'react'

type PropItem = {
  description?: string
  type?: string
  default?: string
  required?: boolean
}

type PropRecord = Record<string, PropItem>

export function createPropsTable(propRecord: PropRecord) {
  return function PropsTable() {
    return (
      <div className='markdown'>
        <table>
          <thead>
            <tr>
              <th>属性</th>
              <th>说明</th>
              <th>类型</th>
              <th>默认值</th>
