export interface InputProps extends BaseProps<'input', typeof CLASSES>, Omit<React.HTMLAttributes<HTMLDivElement>, 'children' | 'prefix'> {
  formControl?: FormControlProvider;
  model?: string;
  defaultModel?: string;
