def:pub getVerticalSidePosition(
    targetEl: HTMLElement,
    popupSize: PopupSize,
    config: VerticalSideConfig
) -> VerticalSidePosition {
    width = popupSize.width;
    height = popupSize.height;
    placement = config.placement;
    placementFixed = config.placementFixed;
    gap = config.gap;
    inWindow = config.inWindow;
    bound = 0.0 if inWindow is False else inWindow as float;

    targetRect = targetEl.getBoundingClientRect();

    def getPosition(
        placementArg: str,
        defaultPosition: VerticalSidePosition | None = None
    ) -> VerticalSidePosition {
        if placementArg in ["top", "top-left", "top-right"] {
            top = targetRect.top - height - gap;
        } else {
            top = targetRect.top + targetRect.height + gap;
        }
        if placementArg in ["top", "bottom"] {
            left = targetRect.left + (targetRect.width - width) / 2;
        } elif placementArg in ["top-left", "bottom-left"] {
            left = targetRect.left;
        } else {
            left = targetRect.left + targetRect.width - width;
        }
        inBound = True;
        for num in [top, ROOT_DATA.windowSize.width - left - width, ROOT_DATA.windowSize.height - top - height, left] {
            if num < bound {
                inBound = False;
                break;
            }
        }
        if inWindow is not False {
            margin = inWindow as float;
            top = min(max(top, margin), ROOT_DATA.windowSize.height - height - margin);
        }
        if inWindow is not False {
            margin = inWindow as float;
            left = min(max(left, margin), ROOT_DATA.windowSize.width - width - margin);
        }
        if placementArg in ["top", "top-left", "top-right"] {
            transformOrigin = "center bottom";
        } else {
            transformOrigin = "center top";
        }
        position = VerticalSidePosition(
            top=top,
            left=left,
            transformOrigin=transformOrigin,
            placement=placementArg,
        );
        if not placementFixed and not inBound {
            if defaultPosition is not None {
                return defaultPosition;
            }
            if "top" in placementArg {
                flipped = placementArg.replace("top", "bottom");
            } else {
                flipped = placementArg.replace("bottom", "top");
            }
            return getPosition(flipped, position);
        }
        return position;
    }

    return getPosition(placement);
}

