enum:pub ConnectionAdvice: str {
    CHECK_NETWORK = "check-network",
    SIGN_IN_AGAIN = "sign-in-again",
    RETRYING = "retrying",
    UNKNOWN = "unknown",
}

obj:pub ConnectionDiagnostics {
    has message: str;
    has advice: ConnectionAdvice;
}

def isHttpError(err: object, status: int) -> bool {
    if not isinstance(err, dict) {
        return False;
    }
    if "status" not in err {
        return False;
    }
    errStatus = err["status"];
    if not isinstance(errStatus, int) {
        return False;
    }
    return errStatus == status;
}

def isUnauthorizedLike(err: object) -> bool {
    if isHttpError(err, 401) or isHttpError(err, 403) {
        return True;
    }
    lower = str(err).lower();
    return (
        "unauthorized" in lower
        or "not authenticated" in lower
        or "session expired" in lower
        or "invalid session" in lower
    );
}

def isNetworkLike(err: object) -> bool {
    if not isinstance(err, Exception) {
        return False;
    }
    msg = str(err);
    lower = msg.lower();
    return (
        "fetch" in lower
        or "network" in lower
        or "failed to connect" in lower
        or "net::err" in lower
        or "enotfound" in lower
        or "econnrefused" in lower
        or msg == "Hermes API is unreachable."
    );
}

def:pub explainConnectionError(err: object) -> ConnectionDiagnostics {
    if isUnauthorizedLike(err) {
        return ConnectionDiagnostics(
            message="Your session expired. Please sign in again.",
            advice=ConnectionAdvice.SIGN_IN_AGAIN,
        );
    }
    if isNetworkLike(err) {
        return ConnectionDiagnostics(
            message="Can't reach your Dashboard. Check your network, Tailscale, or HTTPS setup and try again.",
            advice=ConnectionAdvice.CHECK_NETWORK,
        );
    }
    msg = str(err);
    lower = msg.lower();
    if "ticket" in lower or "websocket" in lower or "ws" in lower {
        return ConnectionDiagnostics(
            message="Live updates disconnected. Retrying…",
            advice=ConnectionAdvice.RETRYING,
        );
    }
    return ConnectionDiagnostics(
        message=msg if msg else "Connection lost. Retrying…",
        advice=ConnectionAdvice.RETRYING,
    );
}

def:pub connectionStateLabel(state: str) -> str {
    switch state {
        case "connected":
            return "Connected";
        case "reconnecting":
            return "Reconnecting…";
        case "ticketing":
            return "Connecting…";
        case "init":
            return "Starting…";
        case "login":
            return "Sign in required";
        case "offline":
            return "Offline";
        case "incompatible-transport":
            return "WebSocket transport unsupported";
        default:
            return state;
    }
}

