def:pub toActionItem(raw: dict[str, object]) -> ActionItem {
    kind = parseActionKind(raw);
    titleVal = raw.get("title");
    title = titleVal if isinstance(titleVal, str) else "Untitled";
    createdVal = raw.get("created_at");
    if isinstance(createdVal, int) {
        createdAt = createdVal;
    } else {
        createdAt = int(time.time() * 1000);
    }
    sessionId: str | None = None;
    sessionIdVal = raw.get("session_id");
    if isinstance(sessionIdVal, str) {
        sessionId = sessionIdVal;
    } else {
        altSessionId = raw.get("sessionId");
        if isinstance(altSessionId, str) {
            sessionId = altSessionId;
        }
    }
    sourceSessionId: str | None = None;
    sourceSessionIdVal = raw.get("source_session_id");
    if isinstance(sourceSessionIdVal, str) {
        sourceSessionId = sourceSessionIdVal;
    } else {
        altSourceSessionId = raw.get("sourceSessionId");
        if isinstance(altSourceSessionId, str) {
            sourceSessionId = altSourceSessionId;
        }
    }
    status = parseActionStatus(raw);
    out = ActionItem(
        id=str(raw.get("id", "")),
        kind=kind,
        status=status,
        title=title,
        createdAt=createdAt,
        sessionId=sessionId,
        sourceSessionId=sourceSessionId,
    );
    if kind == ActionKind.APPROVAL {
        highImpactVal = raw.get("high_impact");
        if highImpactVal is None {
            highImpactVal = raw.get("highImpact");
        }
        out.kind = ActionKind.APPROVAL;
        out.highImpact = bool(highImpactVal);
    }
    if kind == ActionKind.CLARIFY {
        questionVal = raw.get("question");
        out.kind = ActionKind.CLARIFY;
        out.question = questionVal if isinstance(questionVal, str) else "";
    }
    summaryVal = raw.get("summary");
    if isinstance(summaryVal, str) {
        out.summary = summaryVal;
    }
    sessionVal = raw.get("session");
    if isinstance(sessionVal, str) {
        out.session = sessionVal;
    }
    visibilityVal = raw.get("visibility");
    if visibilityVal == "private" or visibilityVal == "public" {
        out.visibility = visibilityVal as str;
    }
    return out;
