import math;
import re;
import time;

type SpawnStatus = str;
type StreamKind = str;

obj StreamEntry {
    has at: int;
    has kind: StreamKind;
    has text: str;
    has isError: bool = False;
}

obj SpawnedAgent {
    has id: str;
    has parentId: str | None;
    has sessionId: str;
    has goal: str;
    has status: SpawnStatus;
    has taskIndex: int;
    has taskCount: int;
    has startedAt: int;
    has updatedAt: int;
    has filesRead: list[str] = [];
    has filesWritten: list[str] = [];
    has stream: list[StreamEntry] = [];
    has model: str | None = None;
    has durationSeconds: float | None = None;
    has inputTokens: float | None = None;
    has outputTokens: float | None = None;
    has costUsd: float | None = None;
    has toolCount: float | None = None;
}

obj SpawnNode {
    has id: str;
    has parentId: str | None;
    has sessionId: str;
    has goal: str;
    has status: SpawnStatus;
    has taskIndex: int;
    has taskCount: int;
    has startedAt: int;
    has updatedAt: int;
    has filesRead: list[str] = [];
    has filesWritten: list[str] = [];
    has stream: list[StreamEntry] = [];
    has children: list[SpawnNode] = [];
    has model: str | None = None;
    has durationSeconds: float | None = None;
    has inputTokens: float | None = None;
    has outputTokens: float | None = None;
    has costUsd: float | None = None;
    has toolCount: float | None = None;
}

glob TERMINAL: set[str] = {"completed", "failed", "interrupted"};
glob MAX_STREAM: int = 24;

def asStr(v: object | None) -> str {
    return v if isinstance(v, str) else "";
}

def asNum(v: object | None) -> float | None {
    if isinstance(v, (int, float)) and math.isfinite(v) {
        return v;
    }
    return None;
}

def asStrList(v: object | None) -> list[str] {
    if isinstance(v, list) {
        return [x for x in v if isinstance(x, str)];
    }
    return [];
}

def asStatus(v: object | None) -> SpawnStatus {
    if v == "completed" or v == "failed" or v == "interrupted" or v == "queued" {
        return v as SpawnStatus;
    }
    return "running";
}

def compact(text: str, max_len: int = 220) -> str {
    line = re.sub(r"\s+", " ", text).strip();
    if len(line) > max_len {
        return line[:max_len - 1] + "…";
    }
    return line;
}

def agentIdFromPayload(p: dict[str, object]) -> str {
    subagent = asStr(p.get("subagent_id"));
    if subagent {
        return subagent;
    }
    parent = asStr(p.get("parent_id")) or "root";
    task_idx = asNum(p.get("task_index"));
    task_idx_str = str(int(task_idx)) if task_idx is not None else "0";
    goal = asStr(p.get("goal"));
    return f"{parent}:{task_idx_str}:{goal}";
}

def agentFromPayload(p: dict[str, object], sessionId: str) -> SpawnedAgent {
    id = agentIdFromPayload(p);
    status = asStatus(p.get("status"));
    toolName = asStr(p.get("tool_name"));
    toolPreview = asStr(p.get("tool_preview")) or asStr(p.get("text"));
    text = compact(asStr(p.get("text")) or toolPreview);
    stream: list[StreamEntry] = [];
    if toolName and status not in TERMINAL {
        snippet = compact(toolPreview, 96) if toolPreview else "";
        words = [w for w in toolName.split("_") if w];
        label = " ".join([w[0].upper() + w[1:] for w in words]);
        stream_text = f"{label}(\"{snippet}\")" if snippet else label;
        stream.append(StreamEntry(at=int(time.time() * 1000), kind="tool", text=stream_text));
    } elif text {
        stream.append(StreamEntry(at=int(time.time() * 1000), kind="progress", text=text));
    }
    parent_raw = asStr(p.get("parent_id"));
    parent_id: str | None = parent_raw if parent_raw else None;
    task_idx = asNum(p.get("task_index"));
    task_count = asNum(p.get("task_count"));
    started = asNum(p.get("started_at"));
    updated = asNum(p.get("updated_at"));
    model_val = asStr(p.get("model"));
    duration = asNum(p.get("duration_seconds"));
    input_tokens = asNum(p.get("input_tokens"));
    output_tokens = asNum(p.get("output_tokens"));
    cost = asNum(p.get("cost_usd"));
    tool_count = asNum(p.get("tool_count"));
    now_ms = int(time.time() * 1000);
    return SpawnedAgent(
        id=id,
        parentId=parent_id,
        sessionId=sessionId,
        goal=asStr(p.get("goal")) or "Task",
        status=status,
        taskIndex=int(task_idx) if task_idx is not None else 0,
        taskCount=int(task_count) if task_count is not None else 1,
        startedAt=int(started) if started is not None else now_ms,
        updatedAt=int(updated) if updated is not None else now_ms,
        filesRead=asStrList(p.get("files_read")),
        filesWritten=asStrList(p.get("files_written")),
        stream=stream,
        model=model_val if model_val else None,
        durationSeconds=duration,
        inputTokens=input_tokens,
        outputTokens=output_tokens,
        costUsd=cost,
        toolCount=tool_count,
    );
}

def buildSpawnTree(agents: list[SpawnedAgent]) -> list[SpawnNode] {
    node_map: dict[str, SpawnNode] = {};
    for a in agents {
        node_map[a.id] = SpawnNode(
            id=a.id,
            parentId=a.parentId,
            sessionId=a.sessionId,
            goal=a.goal,
            status=a.status,
            taskIndex=a.taskIndex,
            taskCount=a.taskCount,
            startedAt=a.startedAt,
            updatedAt=a.updatedAt,
            filesRead=a.filesRead,
            filesWritten=a.filesWritten,
            stream=a.stream,
            children=[],
            model=a.model,
            durationSeconds=a.durationSeconds,
            inputTokens=a.inputTokens,
            outputTokens=a.outputTokens,
            costUsd=a.costUsd,
            toolCount=a.toolCount,
        );
    }
    roots: list[SpawnNode] = [];
    for node in node_map.values() {
        if node.parentId and node.parentId in node_map {
            node_map[node.parentId].children.append(node);
        } else {
            roots.append(node);
        }
    }
    return roots;
}

js:
export type SpawnStatus = 'running' | 'queued' | 'completed' | 'failed' | 'interrupted';
export type StreamKind = 'progress' | 'summary' | 'thinking' | 'tool';

export interface StreamEntry {
  at: number;
  kind: StreamKind;
  text: string;
  isError?: boolean;
}

export interface SpawnedAgent {
  id: string;
  parentId: string | null;
  sessionId: string;
  goal: string;
  model?: string;
  status: SpawnStatus;
  taskIndex: number;
  taskCount: number;
  startedAt: number;
  updatedAt: number;
  durationSeconds?: number;
  inputTokens?: number;
  outputTokens?: number;
  costUsd?: number;
  toolCount?: number;
  filesRead: string[];
  filesWritten: string[];
  stream: StreamEntry[];
}

export interface SpawnNode extends SpawnedAgent {
  children: SpawnNode[];
}

const TERMINAL: ReadonlySet<SpawnStatus> = new Set(['completed', 'failed', 'interrupted']);
const MAX_STREAM = 24;

const str = (v: unknown): string => (typeof v === 'string' ? v : '');
const num = (v: unknown): number | undefined =>
  typeof v === 'number' && Number.isFinite(v) ? v : undefined;
const strList = (v: unknown): string[] =>
  Array.isArray(v) ? (v as unknown[]).filter((x): x is string => typeof x === 'string') : [];
const asStatus = (v: unknown): SpawnStatus =>
  v === 'completed' || v === 'failed' || v === 'interrupted' || v === 'queued' ? v : 'running';

function compact(text: string, max = 220): string {
  const line = text.replace(/\s+/g, ' ').trim();
  return line.length > max ? `${line.slice(0, max - 1)}…` : line;
}

export function agentIdFromPayload(p: Record<string, unknown>): string {
  return (
    str(p.subagent_id) ||
    `${str(p.parent_id) || 'root'}:${String(num(p.task_index) ?? 0)}:${str(p.goal)}`
  );
}

export function agentFromPayload(
  p: Record<string, unknown>,
  sessionId: string,
): SpawnedAgent {
  const id = agentIdFromPayload(p);
  const status = asStatus(p.status);
  const toolName = str(p.tool_name);
  const toolPreview = str(p.tool_preview) || str(p.text);
  const text = compact(str(p.text) || toolPreview);

  const stream: StreamEntry[] = [];
  if (toolName && !TERMINAL.has(status)) {
    const snippet = toolPreview ? compact(toolPreview, 96) : '';
    const label = toolName
      .split('_')
      .filter(Boolean)
      .map((w) => w[0]!.toUpperCase() + w.slice(1))
      .join(' ');
    stream.push({ at: Date.now(), kind: 'tool', text: snippet ? `${label}("${snippet}")` : label });
  } else if (text) {
    stream.push({ at: Date.now(), kind: 'progress', text });
  }

  const agent: SpawnedAgent = {
    id,
    parentId: str(p.parent_id) || null,
    sessionId,
    goal: str(p.goal) || 'Task',
    status,
    taskIndex: num(p.task_index) ?? 0,
    taskCount: num(p.task_count) ?? 1,
    startedAt: num(p.started_at) ?? Date.now(),
    updatedAt: num(p.updated_at) ?? Date.now(),
    filesRead: strList(p.files_read),
    filesWritten: strList(p.files_written),
    stream,
  };
  const model = str(p.model);
  if (model) agent.model = model;
  const durationSeconds = num(p.duration_seconds);
  if (durationSeconds !== undefined) agent.durationSeconds = durationSeconds;
  const inputTokens = num(p.input_tokens);
  if (inputTokens !== undefined) agent.inputTokens = inputTokens;
  const outputTokens = num(p.output_tokens);
  if (outputTokens !== undefined) agent.outputTokens = outputTokens;
  const costUsd = num(p.cost_usd);
  if (costUsd !== undefined) agent.costUsd = costUsd;
  const toolCount = num(p.tool_count);
  if (toolCount !== undefined) agent.toolCount = toolCount;
  return agent;
}

export function mergeAgent(existing: SpawnedAgent, p: Record<string, unknown>): SpawnedAgent {
  const status = asStatus(p.status);
  const toolName = str(p.tool_name);
  const toolPreview = str(p.tool_preview) || str(p.text);
  const text = compact(str(p.text) || toolPreview);

  let newEntry: StreamEntry | null = null;
  if (toolName && !TERMINAL.has(status)) {
    const snippet = toolPreview ? compact(toolPreview, 96) : '';
    const label = toolName
      .split('_')
      .filter(Boolean)
      .map((w) => w[0]!.toUpperCase() + w.slice(1))
      .join(' ');
    newEntry = { at: Date.now(), kind: 'tool', text: snippet ? `${label}("${snippet}")` : label };
  } else if (text) {
    newEntry = { at: Date.now(), kind: 'progress', text };
  }

  const prevStream = existing.stream;
  let stream = prevStream;
  if (newEntry) {
    const last = prevStream.at(-1);
    const isDupe =
      last && last.kind === newEntry.kind && last.text === newEntry.text && !last.isError;
    if (!isDupe) {
      stream = [...prevStream, newEntry].slice(-MAX_STREAM);
    }
  }
  if (TERMINAL.has(status)) {
    const streamText = str(p.summary) || str(p.text);
    if (streamText) {
      stream = [...stream, { at: Date.now(), kind: 'summary' as StreamKind, text: compact(streamText) }].slice(-MAX_STREAM);
    }
  }

  const merged: SpawnedAgent = {
    ...existing,
    status,
    updatedAt: num(p.updated_at) ?? Date.now(),
    filesRead: strList(p.files_read).length ? strList(p.files_read) : existing.filesRead,
    filesWritten: strList(p.files_written).length ? strList(p.files_written) : existing.filesWritten,
    stream,
  };
  const durationSeconds = num(p.duration_seconds) ?? existing.durationSeconds;
  if (durationSeconds !== undefined) merged.durationSeconds = durationSeconds;
  const inputTokens = num(p.input_tokens) ?? existing.inputTokens;
  if (inputTokens !== undefined) merged.inputTokens = inputTokens;
  const outputTokens = num(p.output_tokens) ?? existing.outputTokens;
  if (outputTokens !== undefined) merged.outputTokens = outputTokens;
  const costUsd = num(p.cost_usd) ?? existing.costUsd;
  if (costUsd !== undefined) merged.costUsd = costUsd;
  const toolCount = num(p.tool_count) ?? existing.toolCount;
  if (toolCount !== undefined) merged.toolCount = toolCount;
  return merged;
}

export function buildSpawnTree(agents: SpawnedAgent[]): SpawnNode[] {
  const map = new Map<string, SpawnNode>();
  for (const a of agents) {
    map.set(a.id, { ...a, children: [] });
  }
  const roots: SpawnNode[] = [];
  for (const node of map.values()) {
    if (node.parentId && map.has(node.parentId)) {
      map.get(node.parentId)!.children.push(node);
    } else {
      roots.push(node);
    }
  }
  return roots;
}

