obj TreeNested[T] {
    has children: list[T] | None = None;
}

def:pub findNested[T](
    arr: list[T],
    predicate: Callable[[T], bool],
    arr_nested: Callable[[T], list[T] | None] | None = None,
) -> T | None {
    res: T | None = None;

    def get_children(item: T) -> list[T] | None {
        if arr_nested is not None {
            return arr_nested(item);
        }
        return (item as TreeNested[T]).children;
    }

    def reduce_arr(items: list[T]) -> None {
        for item in items {
            if res is not None {
                break;
            }
            if predicate(item) {
                res = item;
            } else {
                children = get_children(item);
                if children is not None {
                    reduce_arr(children);
                }
            }
        }
    }

    reduce_arr(arr);
    return res;
}

js:
import { isArray, isUndefined } from 'lodash';

export function findNested<T>(arr: T[], predicate: (item: T) => boolean, arrNested = (item: T) => (item as any).children): T | undefined {
  let res: T | undefined;
  const reduceArr = (arr: T[]) => {
    for (const item of arr) {
      if (!isUndefined(res)) {
        break;
      }

      if (predicate(item)) {
        res = item;
      } else {
        const children = arrNested(item);
        if (isArray(children)) {
          reduceArr(children);
        }
      }
    }
  };
  reduceArr(arr);

  return res;
}

