def:pub useComponentProps[T: object](component: str, props: T) -> T {
    context = use(LContext);
    default_props: dict[str, object] = (context.componentDefaultProps[component] if component in context.componentDefaultProps else {}) as dict[str, object];
    defined_props: dict[str, object] = {};
    props_map = props as dict[str, object];
    for key in props_map {
        val = props_map[key];
        if val is not None {
            defined_props[key] = val;
        }
    }
    merged = default_props.copy();
    for key in defined_props {
        merged[key] = defined_props[key];
    }
    return merged as T;
}

js:
import type { ComponentProps } from '../context/props';

import { isUndefined } from 'lodash';
import { use } from 'react';

import { LContext } from '../context';

export function useComponentProps<T extends object>(component: keyof ComponentProps, props: T): T {
  const context = use(LContext);
  const defaultProps: any = context.componentDefaultProps[component] ?? {};
  const definedProps: any = {};
  Object.keys(props).forEach((key) => {
    if (!isUndefined((props as any)[key])) {
      definedProps[key] = (props as any)[key];
    }
  });
  return Object.assign(defaultProps, definedProps);
}

