import from "@chakra-ui/react" { Link as ChakraLink }
import from "react-router" { Link as RouterLink }
import from "react-icons/lu" { LuExternalLink }

def:pub Link(
    children: JsxElement,
    to: str,
    isExternal: bool = False,
    reloadDocument: bool = False,
    fontSize: str | None = None,
    color: str | None = None,
    textDecoration: str | None = None,
    _hover: dict[str, str] | None = None,
) -> JsxElement {
    if isExternal {
        return (
            <ChakraLink
                href={to}
                target="_blank"
                display="inline-flex"
                alignItems="center"
                gap={1}
                fontSize={fontSize}
                color={color}
                textDecoration={textDecoration}
                _hover={_hover}
            >
                {children}
                <LuExternalLink aria-hidden={True} />
            </ChakraLink>
        );
    }
    return (
        <ChakraLink asChild fontSize={fontSize} color={color} textDecoration={textDecoration} _hover={_hover}>
            <RouterLink to={to} reloadDocument={reloadDocument}>
                {children}
            </RouterLink>
        </ChakraLink>
    );
}

