obj ListenerByKey[T] {
    has listeners: dict[str, set[Callable[[object, object], None]]] = {};

    def size() -> int {
        return len(self.listeners);
    }

    def getListeners(key: str) -> set[Callable[[object, object], None]] {
        return self.listeners.get(key, set());
    }

    def subscribe(key: str, listener: Callable[[object, object], None]) -> Callable[[], None] {
        hasListeners = key in self.listeners;
        if hasListeners {
            bucket = self.listeners[key];
            bucket.add(listener);
        }
        if not hasListeners {
            self.listeners[key] = {listener};
        }
        return lambda {
            bucketOpt = self.listeners.get(key);
            if bucketOpt is not None {
                bucketOpt.discard(listener);
                if len(bucketOpt) == 0 {
                    del self.listeners[key];
                }
            }
        };
    }

    def notify(key: str, prev: object, next: object) {
        if key in self.listeners {
            bucket = self.listeners[key];
            for listener in bucket {
                listener(prev, next);
            }
        }
    }

    def clear() {
        self.listeners.clear();
    }
}

