import re;
import from "el-form-core" { setNestedValue, getNestedValue, removeArrayItem, parseZodErrors }

def _is_numeric_key(key: str) -> bool {
    try {
        _ = int(key);
        return True;
    } except ValueError {
        return False;
    }
}

def _shallow_clone_nested(value: object) -> object {
    if isinstance(value, list) {
        return [v for v in (value as list[object])];
    }
    if isinstance(value, dict) {
        return {k: v for (k, v) in (value as dict[str, object]).items()};
    }
    return value;
}

def:pub addArrayItemReact(`obj: dict[str, object], path: str, item: object) -> dict[str, object] {
    result: dict[str, object] = {**`obj};
    normalized_path: str = re.sub(r"\[(\d+)\]", r".\1", path);
    keys: list[str] = [key for key in normalized_path.split(".") if key != ""];
    current: object = result;
    i: int = 0;
    while i < len(keys) - 1 {
        key: str = keys[i];
        if _is_numeric_key(key) {
            idx: int = int(key);
            if isinstance(current, list) {
                arr: list[object] = current as list[object];
                nested: object = arr[idx];
                arr[idx] = _shallow_clone_nested(nested);
                current = arr[idx];
            }
        } elif isinstance(current, dict) {
            cur: dict[str, object] = current as dict[str, object];
            nested = cur.get(key);
            if nested is None or (not isinstance(nested, dict) and not isinstance(nested, list)) {
                cur[key] = {};
                nested = cur[key];
            } else {
                cur[key] = _shallow_clone_nested(nested);
                nested = cur[key];
            }
            current = nested;
        }
        i += 1;
    }
    array_key: str = keys[len(keys) - 1];
    if _is_numeric_key(array_key) {
        idx_final: int = int(array_key);
        if isinstance(current, list) {
            arr_final: list[object] = [v for v in (current as list[object])];
            arr_final[idx_final] = item;
        }
    } elif isinstance(current, dict) {
        cur_final: dict[str, object] = current as dict[str, object];
        existing_arr = cur_final.get(array_key);
        if not isinstance(existing_arr, list) {
            cur_final[array_key] = [item];
        } else {
            new_arr: list[object] = [v for v in (existing_arr as list[object])];
            new_arr.append(item);
            cur_final[array_key] = new_arr;
        }
    }
    return result;
}

