        arr1 = obj1 as list[object];
        arr2 = obj2 as list[object];
        if len(arr1) != len(arr2) { return False; }
        for i = 0 while i < len(arr1) with i += 1 {
            if not deepEqual(arr1[i], arr2[i]) { return False; }
