def:pub findFirstErrorElement(
    errors: dict[str, object],
    resolve: Callable[[str], object | None]
) -> object | None {
    for name in list(errors.keys()) {
        if not errors[name] { continue; }
        el = resolve(name);
        if el is not None {
            focus = getattr(el, "focus", None);
            if focus is not None and callable(focus) {
                return el;
            }
        }
    }
    return None;
}

