import from "zod" { z, ZodTypeAny }

def:pub zodArrayIgnoreUnknown(zodType: ZodTypeAny) -> ZodTypeAny {
    isKnownItem = lambda (item: object) -> bool {
        return zodType.safeParse(item).success;
    };
    return z.preprocess(
        lambda (val: object) -> list[object] {
            return [item for item in toSafeArray(val) if isKnownItem(item)];
        },
        z.array(zodType)
    );
}

def toSafeArray(item: object) -> list[object] {
    if isArray(item) {
        return item as list[object];
    }
    return [item];
}

def isArray(item: object) -> bool {
