glob TEMPLATE_REGEX = re.compile(r"\{\{([^{}]+)\}\}");

def:pub template(str: str, data: dict[str, object]) -> str {
    acc = str;
    for match in TEMPLATE_REGEX.finditer(str) {
        path = match.group(1).strip();
        value = getByPath[object](data, path);
        replacement = "undefined" if value is None else str(value);
        acc = acc.replace(match.group(0), replacement);
    }
    return acc;
}

