import math;
import re;


def:pub formatNumber(val: int | str, decimal: int = 2, autoPadZero: bool = True) -> str {
    num = float(str(val));
    if math.isnan(num) {
        return "-";
    }
    parts = str(num).split(".");
    b = parts[1] if len(parts) > 1 else None;
    trunc_str = f"{int(num):,}";
    str_val = f"{trunc_str}.{b}" if b is not None else trunc_str;
    if autoPadZero {
        split_parts = str_val.split(".");
        a = split_parts[0];
        b_part = split_parts[1] if len(split_parts) > 1 else "";
        if len(b_part) < decimal {
            str_val = f"{a}.{b_part}{'0' * (decimal - len(b_part))}";
        }
    }
    if decimal == 0 {
        return re.sub(r"\.\d*$", "", str_val);
    }
    return re.sub(r"\.\d*$", lambda (m: re.Match[str]) { m.group(0)[:decimal + 1] }, str_val);
}


def:pub trimInputValue(form: dict[str, object], name: str, e: object | str) {
    val: str;
    if isinstance(e, str) {
        val = e;
    } else {
        event = e as dict[str, object];
        target = event["target"] as dict[str, object] | None;
        val = (target?["value"] as str) or "";
    }
    setter = form["setFieldsValue"] as Callable[[dict[str, str]], None];
    setter({name: val.strip()});
}

