import { join } from 'path'
import { readFileSync, writeFileSync, existsSync } from 'fs'
import { getDataDir } from '../paths'
import { createLogger } from '../../shared/logger'

const log = createLogger('DeviceToken')

const TOKEN_FILE = 'device-auth-tokens.json'

interface DeviceAuthEntry {
   token: string
   role: string
   scopes: string[]
   updatedAtMs: number
}

interface DeviceAuthStore {
   version: 1
   deviceId: string
   tokens: Record<string, DeviceAuthEntry>
}

function getTokenPath(): string {
   return join(getDataDir(), TOKEN_FILE)
}

function readStore(): DeviceAuthStore | null {
   const tokenPath = getTokenPath()
   if (!existsSync(tokenPath)) {
      log.debug('readStore: file not found at %s', tokenPath)
      return null
   }
   try {
      const raw = readFileSync(tokenPath, 'utf-8')
      const data = JSON.parse(raw)
      if (data?.version === 1 && typeof data.deviceId === 'string' && data.tokens) {
         log.debug(
            'readStore: loaded, deviceId=%s, tokenCount=%d',
            data.deviceId,
            Object.keys(data.tokens).length,
         )
         return data as DeviceAuthStore
      }
      log.warn('readStore: invalid store format')
      return null
   } catch (err) {
      log.error('readStore: parse error:', err)
      return null
   }
}

function writeStore(store: DeviceAuthStore): void {
   const tokenPath = getTokenPath()
   writeFileSync(tokenPath, JSON.stringify(store, null, 2), 'utf-8')
   log.debug('writeStore: saved to %s', tokenPath)
}

function normalizeRole(role: string): string {
   return role.trim().toLowerCase() || 'operator'
}

export function loadDeviceAuthToken(params: {
   deviceId: string
   role: string
}): DeviceAuthEntry | null {
   log.log(
      'loadDeviceAuthToken: deviceId=%s, role=%s',
      params.deviceId,
      params.role,
   )
   const store = readStore()
   if (!store || store.deviceId !== params.deviceId) {
      log.log(
         'loadDeviceAuthToken: no match (storeDeviceId=%s)',
         store?.deviceId ?? 'none',
      )
      return null
   }
   const key = normalizeRole(params.role)
   const entry = store.tokens[key] ?? null
   log.log(
      'loadDeviceAuthToken: found=%s',
      entry ? 'yes' : 'no',
   )
   return entry
}

export function storeDeviceAuthToken(params: {
   deviceId: string
   role: string
   token: string
   scopes?: string[]
}): void {
   log.log(
      'storeDeviceAuthToken: deviceId=%s, role=%s',
      params.deviceId,
      params.role,
   )
   const key = normalizeRole(params.role)
   let store = readStore()
   if (!store || store.deviceId !== params.deviceId) {
      log.log('storeDeviceAuthToken: creating new store')
      store = { version: 1, deviceId: params.deviceId, tokens: {} }
   }
   store.tokens[key] = {
      token: params.token,
      role: params.role,
      scopes: params.scopes ?? [],
      updatedAtMs: Date.now(),
   }
   writeStore(store)
   log.log('storeDeviceAuthToken: stored successfully')
}

export function clearDeviceAuthToken(params: {
   deviceId: string
   role: string
}): void {
   log.log(
      'clearDeviceAuthToken: deviceId=%s, role=%s',
      params.deviceId,
      params.role,
   )
   const store = readStore()
   if (!store || store.deviceId !== params.deviceId) {
      log.log('clearDeviceAuthToken: no matching store')
      return
   }
   const key = normalizeRole(params.role)
   if (!(key in store.tokens)) {
      log.log('clearDeviceAuthToken: token not found for role=%s', key)
      return
   }
   delete store.tokens[key]
   writeStore(store)
   log.log('clearDeviceAuthToken: cleared successfully')
}

import type { GatewayErrorInfo } from '../../shared/types/gateway-protocol'

// ── ConnectErrorDetailCodes ──
// 从 openclaw/src/gateway/protocol/connect-error-details.ts 移植

export const ConnectErrorDetailCodes = {
   AUTH_REQUIRED: 'AUTH_REQUIRED',
   AUTH_UNAUTHORIZED: 'AUTH_UNAUTHORIZED',
   AUTH_TOKEN_MISSING: 'AUTH_TOKEN_MISSING',
   AUTH_TOKEN_MISMATCH: 'AUTH_TOKEN_MISMATCH',
   AUTH_TOKEN_NOT_CONFIGURED: 'AUTH_TOKEN_NOT_CONFIGURED',
   AUTH_PASSWORD_MISSING: 'AUTH_PASSWORD_MISSING',
   AUTH_PASSWORD_MISMATCH: 'AUTH_PASSWORD_MISMATCH',
   AUTH_PASSWORD_NOT_CONFIGURED: 'AUTH_PASSWORD_NOT_CONFIGURED',
   AUTH_BOOTSTRAP_TOKEN_INVALID: 'AUTH_BOOTSTRAP_TOKEN_INVALID',
   AUTH_DEVICE_TOKEN_MISMATCH: 'AUTH_DEVICE_TOKEN_MISMATCH',
   AUTH_RATE_LIMITED: 'AUTH_RATE_LIMITED',
   AUTH_TAILSCALE_IDENTITY_MISSING: 'AUTH_TAILSCALE_IDENTITY_MISSING',
   AUTH_TAILSCALE_PROXY_MISSING: 'AUTH_TAILSCALE_PROXY_MISSING',
   AUTH_TAILSCALE_WHOIS_FAILED: 'AUTH_TAILSCALE_WHOIS_FAILED',
   AUTH_TAILSCALE_IDENTITY_MISMATCH: 'AUTH_TAILSCALE_IDENTITY_MISMATCH',
   CONTROL_UI_ORIGIN_NOT_ALLOWED: 'CONTROL_UI_ORIGIN_NOT_ALLOWED',
   CONTROL_UI_DEVICE_IDENTITY_REQUIRED: 'CONTROL_UI_DEVICE_IDENTITY_REQUIRED',
   DEVICE_IDENTITY_REQUIRED: 'DEVICE_IDENTITY_REQUIRED',
   DEVICE_AUTH_INVALID: 'DEVICE_AUTH_INVALID',
   DEVICE_AUTH_DEVICE_ID_MISMATCH: 'DEVICE_AUTH_DEVICE_ID_MISMATCH',
   DEVICE_AUTH_SIGNATURE_EXPIRED: 'DEVICE_AUTH_SIGNATURE_EXPIRED',
   DEVICE_AUTH_NONCE_REQUIRED: 'DEVICE_AUTH_NONCE_REQUIRED',
   DEVICE_AUTH_NONCE_MISMATCH: 'DEVICE_AUTH_NONCE_MISMATCH',
   DEVICE_AUTH_SIGNATURE_INVALID: 'DEVICE_AUTH_SIGNATURE_INVALID',
   DEVICE_AUTH_PUBLIC_KEY_INVALID: 'DEVICE_AUTH_PUBLIC_KEY_INVALID',
   PAIRING_REQUIRED: 'PAIRING_REQUIRED',
} as const

export type ConnectErrorDetailCode =
   (typeof ConnectErrorDetailCodes)[keyof typeof ConnectErrorDetailCodes]

// ── GatewayRequestError ──

export class GatewayRequestError extends Error {
   readonly gatewayCode: string
   readonly details?: unknown

   constructor(error: GatewayErrorInfo) {
      super(error.message)
      this.name = 'GatewayRequestError'
      this.gatewayCode = error.code
      this.details = error.details
   }
}

// ── 工具函数 ──

export function resolveGatewayErrorDetailCode(
   error: { details?: unknown } | null | undefined,
): string | null {
   if (!error?.details || typeof error.details !== 'object' || Array.isArray(error.details)) {
      return null
   }
   const code = (error.details as { code?: unknown }).code
   return typeof code === 'string' && code.trim().length > 0 ? code : null
}

type ConnectRecoveryNextStep =
   | 'retry_with_device_token'
   | 'update_auth_configuration'
   | 'update_auth_credentials'
   | 'wait_then_retry'
   | 'review_auth_configuration'

const CONNECT_RECOVERY_NEXT_STEP_VALUES: ReadonlySet<ConnectRecoveryNextStep> = new Set([
   'retry_with_device_token',
   'update_auth_configuration',
   'update_auth_credentials',
   'wait_then_retry',
   'review_auth_configuration',
])

export interface ConnectErrorRecoveryAdvice {
   canRetryWithDeviceToken?: boolean
   recommendedNextStep?: ConnectRecoveryNextStep
}

export function readConnectErrorRecoveryAdvice(
   details: unknown,
): ConnectErrorRecoveryAdvice {
   if (!details || typeof details !== 'object' || Array.isArray(details)) {
      return {}
   }
   const raw = details as {
      canRetryWithDeviceToken?: unknown
      recommendedNextStep?: unknown
   }
   const canRetryWithDeviceToken =
      typeof raw.canRetryWithDeviceToken === 'boolean' ? raw.canRetryWithDeviceToken : undefined
   const normalizedNextStep =
      typeof raw.recommendedNextStep === 'string' ? raw.recommendedNextStep.trim() : ''
   const recommendedNextStep = CONNECT_RECOVERY_NEXT_STEP_VALUES.has(
      normalizedNextStep as ConnectRecoveryNextStep,
   )
      ? (normalizedNextStep as ConnectRecoveryNextStep)
      : undefined
   return { canRetryWithDeviceToken, recommendedNextStep }
}

/**
 * 不可恢复的认证错误 — 不应自动重连。
 *
 * 注意：AUTH_TOKEN_MISMATCH 故意不在此列表中，
 * 因为客户端支持使用缓存设备令牌进行一次性重试。
 */
export function isNonRecoverableAuthError(
   error: GatewayErrorInfo | undefined,
): boolean {
   if (!error) {
      return false
   }
   const code = resolveGatewayErrorDetailCode(error)
   return (
      code === ConnectErrorDetailCodes.AUTH_TOKEN_MISSING ||
      code === ConnectErrorDetailCodes.AUTH_BOOTSTRAP_TOKEN_INVALID ||
      code === ConnectErrorDetailCodes.AUTH_PASSWORD_MISSING ||
      code === ConnectErrorDetailCodes.AUTH_PASSWORD_MISMATCH ||
      code === ConnectErrorDetailCodes.AUTH_RATE_LIMITED ||
      code === ConnectErrorDetailCodes.PAIRING_REQUIRED ||
      code === ConnectErrorDetailCodes.CONTROL_UI_DEVICE_IDENTITY_REQUIRED ||
      code === ConnectErrorDetailCodes.DEVICE_IDENTITY_REQUIRED
   )
}

