import from http { ServerResponse }

obj CacheConfig {
    has maxAge: int | None = 10;
    has swr: int | None = 60;
}

def getCacheConfig(config: CacheConfig | None = None) -> str {
    max_age: int | None = 10;
    swr_val: int | None = 60;
    if config is not None {
        max_age = config.maxAge;
        swr_val = config.swr;
    }
    type_section = "public";
    max_age_section = "" if max_age is None else f"max-age={max_age}";
    stale_section = "" if swr_val is None else f"stale-while-revalidate={swr_val}";
    parts: list[str] = [type_section];
    if max_age_section {
        parts.append(max_age_section);
    }
    if stale_section {
        parts.append(stale_section);
    }
    return ", ".join(parts);
}

def:pub setCacheHeader(res: ServerResponse, config: CacheConfig | None = None) {
    res.setHeader("Cache-Control", getCacheConfig(config));
}

js:
import type { ServerResponse } from 'http';

export const setCacheHeader = (res: ServerResponse, config?: CacheConfig) =>
	res.setHeader('Cache-Control', getCacheConfig(config));

interface CacheConfig {
	maxAge?: null | number; // max-age (seconds)
	swr?: null | number; // stale-while-revalidation (seconds)
}

const getCacheConfig = ({
	maxAge = 10,
	swr = 60,
}: CacheConfig = {}): string => {
	const typeSection = 'public';
	const maxAgeSection = maxAge === null ? '' : `max-age=${maxAge}`;
	const staleSection = swr === null ? '' : `stale-while-revalidate=${swr}`;

	return [typeSection, maxAgeSection, staleSection].filter(Boolean).join(', ');
};

