def:pub shallow(a: object, b: object) -> bool {
    if a is b {
        return True;
    }
    if (
        not isinstance(a, dict)
        or a is None
        or not isinstance(b, dict)
        or b is None
    ) {
        return False;
    }
    a_map = a as dict[str, object];
    b_map = b as dict[str, object];
    keys_a = list(a_map.keys());
    keys_b = list(b_map.keys());
    if len(keys_a) != len(keys_b) {
        return False;
    }
    for key in keys_a {
        if key not in b_map or not (a_map[key] is b_map[key]) {
            return False;
        }
    }
    return True;
}

