    loader_opts = opts if opts is not None else ctx.dataLoaderOptions;
    neos_data = await (loadPreviewDocumentPropsCached(ctx.contextNodePath, loader_opts) if ctx.inBackend else loadDocumentPropsCached(ctx.routePath, loader_opts));
    if not neos_data {
        path = ctx.contextNodePath if ctx.inBackend else ctx.routePath;
        raise ValueError(f"Node not found: {path}");
    }
    if hasattr(neos_data, "meta") {
        return neos_data.meta;
