obj AgentOption {
    has id: str;
    has label: str;
}

obj ModelOption {
    has id: str;
    has name: str;
    has provider: str;
}

def:pub NewSessionModal(
    open: bool,
    onClose: Callable[[], None],
    onCreate: Callable[[str, str | None, str | None], None],
    agentOptions: list[AgentOption] = [],
    defaultAgentId: str | None = None,
    defaultAgentLabel: str | None = None,
    models: list[ModelOption] = [],
    preferredModel: str | None = None,
    onPreferredModelChange: Callable[[str | None], None] | None = None
) -> JsxElement {
    has label: str = "";
    has selectedAgentId: str = "";
    has selectedModel: str = "";

    can with [open, preferredModel] entry {
        if open {
            selectedModel = preferredModel or "";
        } else {
            label = "";
            selectedAgentId = "";
            selectedModel = "";
        }
    }

    def submit() {
        trimmed = label.strip();
        agentId = selectedAgentId.strip();
        model = selectedModel.strip();
        onCreate(trimmed, agentId or None, model or None);
        if onPreferredModelChange {
            onPreferredModelChange(model or None);
        }
        label = "";
        selectedAgentId = "";
        selectedModel = "";
    }

    def on_label_change(e: ChangeEvent) {
        label = e.target.value;
    }

    def on_label_keydown(e: KeyboardEvent) {
        if e.key == "Enter" {
            e.preventDefault();
            submit();
        }
    }

    def on_agent_change(e: ChangeEvent) {
        selectedAgentId = e.target.value;
    }

    def on_model_change(e: ChangeEvent) {
        selectedModel = e.target.value;
    }

    if not open {
        return <></>;
    }

    defaultAgentText = (
        (defaultAgentLabel.strip() if defaultAgentLabel else "")
        or (defaultAgentId.strip() if defaultAgentId else "")
        or "main"
    );

    modelChoices: list[dict[str, str]] = [
        {
            "full": f"{m.provider}/{m.id}",
            "id": m.id,
            "name": m.name,
            "provider": m.provider,
        }
        for m in models
    ];

    <div className="modal-backdrop compact">
        <div className="new-session-modal">
            <div className="modal-title">New session</div>
            <p className="modal-subtitle">
                Optional name. If blank, timestamp will be used. Model choice is remembered for next time.
            </p>

            <input
                value={label}
                onChange={on_label_change}
                onKeyDown={on_label_keydown}
                className="ui-input"
                placeholder="e.g. Sprint planning"
            />

            <div className="field-label">Agent</div>
            <select
                value={selectedAgentId}
                onChange={on_agent_change}
                className="ui-input"
                aria-label="Select agent for new session"
            >
                <option value="">Default ({defaultAgentText})</option>
                {for agent in agentOptions {
                    <option key={agent.id} value={agent.id}>
                        {agent.label} ({agent.id})
                    </option>
                }}
            </select>

            <div className="field-label">Model</div>
            <select
                value={selectedModel}
                onChange={on_model_change}
                className="ui-input"
                aria-label="Select model for new session"
            >
                <option value="">System default</option>
                {for model in modelChoices {
                    <option key={model["full"]} value={model["full"]}>
                        {model["full"]}
                    </option>
                }}
            </select>

            <div className="new-session-actions">
                <button type="button" onClick={onClose} className="ui-button">
                    Cancel
                </button>
                <button type="button" onClick={submit} className="ui-button primary">
                    Create
                </button>
            </div>
        </div>
    </div>
}

