async def postContactForm(data: dict[str, str]) -> bool {
    name = data.get("name", "");
    email = data.get("email", "");
    message = data.get("message", "");
    if not name or not email or not message {
        return False;
    }
    post_data = MessageFormData(name=name, email=email, message=message);
    try {
        await fetch(
            "/.netlify/functions/contactForm",
            method="POST",
            headers={"Content-Type": "application/json"},
            body=json.dumps({
                "name": post_data.name,
                "email": post_data.email,
                "message": post_data.message,
            }),
        );
        return True;
    } except Exception {
        return False;
    }
}

