def:pub patchWebpackConfig(config: dict[str, object]) -> dict[str, object] {
    mdxExt = ".mdx";
    mdx2Loader = "@storybook/mdx2-csf";
    rules = config["module"]["rules"] as list[dict[str, object]];
    mdxRules = [rule for rule in rules if rule.get("test") and mdxExt in str(rule["test"])];
