        if use and len(use) > 0 {
            loader = use[0].get("loader", "") as str;
            if mdx2Loader in loader {
                options = use[0]["options"] as dict[str, object];
                compile_opts = options["mdxCompileOptions"] as dict[str, object];
                plugins = compile_opts["remarkPlugins"] as list[object];
                compile_opts["remarkPlugins"] = plugins + [remarkMdxCodeMeta];
            }
        }
    }
    return config;
}

