type PersistedEntry = dict[str, object];

def:pub hasOwnPersistedKey(`entry: PersistedEntry, key: str) -> bool {
    return key in `entry;
}

def:pub parsePersistedEntry(`entry: str | None) -> PersistedEntry {
    if `entry is None {
