def:pub Svg(
    viewBox: str | None = None,
    fill: str = "currentColor",
    size: int | None = None,
    width: int | None = None,
    height: int | None = None,
    children: JsxElement | str | int | list[object] | None = None,
    ref: Ref[SVGElement] = Ref(),
) -> JsxElement {
    resolved_view = viewBox if viewBox else "0 0 24 24";
    resolved_width = size if size else (width if width else 24);
    resolved_height = size if size else (height if height else 24);
    <svg
        viewBox={resolved_view}
        ref={ref}
        fill={fill}
        width={resolved_width}
        height={resolved_height}
        xmlns="http://www.w3.org/2000/svg"
    >
        {children}
    </svg>
}

