/**
 * Shared filters for the geo-logs page (country/city/IP include/IP exclude/
 * hostname). Unlike the analytics filters, the state itself lives in the URL
 * search params (shareable filter links): the /geo-logs route computes the
 * filter state from its validated search and implements setFilters via
 * router.navigate, then mounts this provider as a plain conduit.
 */
import { createContext, useContext } from "react"

export interface GeoLogFilterState {
  countryCodes: string[]
  cities: string[]
  ips: string[]
  ipsExclude: string[]
  hostnames: string[]
}

export const EMPTY_GEO_LOG_FILTERS: GeoLogFilterState = {
  countryCodes: [],
  cities: [],
  ips: [],
  ipsExclude: [],
  hostnames: [],
}

export function hasActiveGeoLogFilters(filters: GeoLogFilterState): boolean {
  return (
    filters.countryCodes.length > 0 ||
    filters.cities.length > 0 ||
    filters.ips.length > 0 ||
    filters.ipsExclude.length > 0 ||
    filters.hostnames.length > 0
  )
}

interface GeoLogFiltersValue {
  filters: GeoLogFilterState
  setFilters: (updater: (prev: GeoLogFilterState) => GeoLogFilterState) => void
}

// Default = empty filters: hooks keep working outside the provider.
const GeoLogFiltersContext = createContext<GeoLogFiltersValue>({
  filters: EMPTY_GEO_LOG_FILTERS,
  setFilters: () => {},
})

export function GeoLogFiltersProvider({
  filters,
  setFilters,
  children,
}: GeoLogFiltersValue & { children: React.ReactNode }) {
  return (
    <GeoLogFiltersContext.Provider value={{ filters, setFilters }}>
      {children}
    </GeoLogFiltersContext.Provider>
  )
}

export function useGeoLogFilters() {
  return useContext(GeoLogFiltersContext)
}

/**
 * Which live overlays are switched on. One key holding an object rather than
 * a bare boolean, so there is a single place to migrate when an overlay is
 * added or renamed. Unknown keys from an older build are ignored.
 */
export const LIVE_OVERLAYS_STORAGE_KEY = "geometrikks-live-overlays"

export interface LiveOverlayPreferences {
  /** The desktop live rail: summary, origins, and the request feed. */
  rail: boolean
}

const DEFAULTS: LiveOverlayPreferences = { rail: true }

export function loadLiveOverlays(): LiveOverlayPreferences {
  try {
    const raw = localStorage.getItem(LIVE_OVERLAYS_STORAGE_KEY)
    if (!raw) return { ...DEFAULTS }
    const parsed = JSON.parse(raw) as Partial<Record<keyof LiveOverlayPreferences, unknown>>
    return {
      rail: typeof parsed.rail === "boolean" ? parsed.rail : DEFAULTS.rail,
    }
  } catch {
    // Storage may be blocked or hold junk; the defaults are always safe.
    return { ...DEFAULTS }
  }
}

export function saveLiveOverlays(preferences: LiveOverlayPreferences): void {
  try {
    localStorage.setItem(LIVE_OVERLAYS_STORAGE_KEY, JSON.stringify(preferences))
  } catch {
    // Keep the in-memory preference for this session.
  }
}

