}

def:pub planLogoutRoute(result: MeResult) -> dict[str, object] {
    if result.ok {
        me = result.me as MeResponse;
        if me.mode == "session" {
            return {"action": "endSessionThenRedirect", "to": "/login"};
        }
        return {"action": "redirect", "to": "/"};
