def:pub AltcoinSeason(data: list[Coin]) -> JsxElement {
    has altSeasonIndex: int = 0;

    can with entry {
        bitcoin: Coin | None = None;
        for coin in data {
            if coin.symbol == "BTC" {
                bitcoin = coin;
                break;
            }
        }
        if bitcoin is None {
            print("Bitcoin not found in the data.");
        } else {
            bitcoinChange90d = bitcoin.quote.USD.percent_change_90d;
            altcoins = [coin for coin in data if coin.symbol != "BTC"];
            betterThanBitcoin = [
                coin for coin in altcoins
                if coin.quote.USD.percent_change_90d > bitcoinChange90d
            ];
            if len(altcoins) > 0 {
                altSeasonIndex = round((len(betterThanBitcoin) / len(altcoins)) * 100);
            }
        }
    }

    <>
        <div style={{"width": "100%", "display": "flex", "marginTop": "24px", "marginBottom": "24px", "alignItems": "center"}}>
