          left: altSeasonIndex + '%',
          color: altSeasonIndex < 25 ? '#F7931A' : altSeasonIndex < 50 ? '#fcdbb9' : altSeasonIndex < 75 ? '#c1ccfd' : '#6c24e0',
          transition: 'all 1s ease'
        }} />
