import from "@mui/icons-material/Launch" { default as LaunchIcon }

def CopyRow(label: str, value: str, link: str | None = None) -> JsxElement {
    has copied: bool = False;

    def handle_copy(e: MouseEvent) {
        navigator.clipboard.writeText(value);
        copied = True;
        setTimeout(lambda { copied = False; }, 2000);
    }

    def handle_link_click(e: MouseEvent) {
        if link {
            window.open(link, "_blank");
        }
    }

    <Stack direction="row" alignItems="center" justifyContent="space-between" sx={{"py": 1}}>
        <Box>
            <Typography variant="body2" color="text.secondary" gutterBottom>{label}</Typography>
            <Typography variant="body1" sx={{"fontWeight": "medium", "wordBreak": "break-all"}}>{value}</Typography>
        </Box>
        {if link {
            <Tooltip title="Перейти по ссылке">
                <IconButton onClick={handle_link_click} color="primary">
                    <LaunchIcon fontSize="small" />
                </IconButton>
            </Tooltip>
        } else {
            <Tooltip title={("Скопировано!" if copied else "Копировать")}>
                <IconButton
                    onClick={handle_copy}
                    color={("success" if copied else "default")}
                    sx={{"ml": 2, "bgcolor": "rgba(255,255,255,0.05)"}}
                >
                    {(<CheckIcon fontSize="small" /> if copied else <ContentCopyIcon fontSize="small" />)}
                </IconButton>
            </Tooltip>
        }}
    </Stack>
}

