import { useState } from 'react';
import {
    Dialog, DialogTitle, DialogContent, DialogActions,
    Button, Typography, Box, IconButton, Tooltip, Stack, Divider
} from '@mui/material';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import CheckIcon from '@mui/icons-material/Check';
import CloseIcon from '@mui/icons-material/Close';
import LaunchIcon from '@mui/icons-material/Launch';

interface SupportModalProps {
    open: boolean;
    onClose: () => void;
}

const CopyRow = ({ label, value, link }: { label: string, value: string, link?: string }) => {
    const [copied, setCopied] = useState(false);

    const handleCopy = () => {
        navigator.clipboard.writeText(value);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    const handleLinkClick = () => {
        if (link) {
            window.open(link, '_blank');
        }
    };

    return (
        <Stack direction="row" alignItems="center" justifyContent="space-between" sx={{ py: 1 }}>
            <Box>
                <Typography variant="body2" color="text.secondary" gutterBottom>
                    {label}
                </Typography>
                <Typography variant="body1" sx={{ fontWeight: 'medium', wordBreak: 'break-all' }}>
                    {value}
                </Typography>
            </Box>
            {link ? (
                <Tooltip title="Перейти по ссылке">
                    <IconButton
                        onClick={handleLinkClick}
                        color="primary"
                    >
                        <LaunchIcon fontSize="small" />
                    </IconButton>
                </Tooltip>
            ) : (
                <Tooltip title={copied ? "Скопировано!" : "Копировать"}>
                    <IconButton
                        onClick={handleCopy}
                        color={copied ? "success" : "default"}
                        sx={{ ml: 2, bgcolor: 'rgba(255,255,255,0.05)' }}
                    >
                        {copied ? <CheckIcon fontSize="small" /> : <ContentCopyIcon fontSize="small" />}
                    </IconButton>
                </Tooltip>
            )}
        </Stack>
    );
};

