import json;
import base64;

def base64UrlDecode(s: str) -> str {
    base64_str = s.replace("-", "+").replace("_", "/");
    pad_len = (4 - (len(base64_str) % 4)) % 4;
    padded = base64_str + ("=" * pad_len);
    return base64.b64decode(padded).decode("utf-8");
}

def decodeJwt[T](token: str) -> T {
    parts = token.split(".");
    if len(parts) != 3 {
        raise InvalidTokenError("Invalid JWT format: expected 3 segments");
    }
    payload_segment = parts[1];
    if not payload_segment {
        raise InvalidTokenError("Invalid JWT format: missing payload segment");
    }
    try {
        decoded = base64UrlDecode(payload_segment);
        return json.loads(decoded) as T;
    } except InvalidTokenError {
        raise;
    } except Exception {
        raise InvalidTokenError("Invalid JWT: malformed payload");
    }
}

