import from "react" { useEffect, useRef }

def:pub useIsOverByScroll() -> dict[str, object] {
    ref = useRef(None);
    has isOverByScroll: bool = False;

    useEffect(lambda {
        rectHeight = 0.0;
        if ref.current {
            rectHeight = ref.current.getBoundingClientRect().height;
        }
        def scroll_event() -> None {
            if rectHeight and window.scrollY > rectHeight {
                isOverByScroll = True;
                return;
            }
            isOverByScroll = False;
        }
        document.addEventListener("scroll", scroll_event);
        return lambda {
            document.removeEventListener("scroll", scroll_event);
        };
    }, []);

    return {"ref": ref, "isOverByScroll": isOverByScroll};
}

