import type { MetadataRoute } from "next";

const SITE = "https://ForSaleSpokane.com";

export default function sitemap(): MetadataRoute.Sitemap {
  const now = new Date();
  const routes = [
    "",
    "/spokane-realtor",
    "/spokane-real-estate-agent",
    "/for-sale-spokane",
    "/homes-for-sale-spokane",
    "/spokane-valley",
    "/sell-my-spokane-home",
    "/about-joey-costello",
    "/game",
    "/neighborhoods",
  ];
  return routes.map((path) => ({
    url: `${SITE}${path}`,
    lastModified: now,
    changeFrequency: "weekly" as const,
    priority: path === "" ? 1.0 : 0.8,
  }));
}

